```tsx
import React, { useState, useEffect } from 'react';
import { Invoice, InvoiceItem } from './types';
import { calculateTotal } from './utils';

// Make sure you import any utility functions and styles here

interface InvoiceFormProps {
  initialInvoice?: Invoice;
  onSubmit: (invoice: Invoice) => void;
  onCancel: () => void;
  // This is a test function that makes it easier to test.
  onPreview?: () => void;
}

const InvoiceForm: React.FC<InvoiceFormProps> = ({ initialInvoice, onSubmit, onCancel, onPreview }) => {
  const [invoice, setInvoice] = useState<Invoice>(initialInvoice || {
    date: new Date().toISOString().split('T')[0],
    invoiceItems: [],
    billFrom: '',
    billTo: '',
    paymentTerms: '',
  });

  const [savedTerms, setSavedTerms] = useState<string[]>([]);
  const [isAddingTerm, setIsAddingTerm] = useState(false);
  const [customTermInput, setCustomTermInput] = useState('');

  const today = new Date().toISOString().split('T')[0];

  useEffect(() => {
    const storedTerms = localStorage.getItem('savedTerms');
    if (storedTerms) {
      setSavedTerms(JSON.parse(storedTerms));
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('savedTerms', JSON.stringify(savedTerms));
  }, [savedTerms]);

  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = event.target;
    setInvoice(prevInvoice => ({
      ...prevInvoice,
      [name]: value,
    }));
  };

  const handleTermChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const selectedTerm = e.target.value;
    setInvoice(prev => ({ ...prev, paymentTerms: selectedTerm }));
  };

  const addCustomTerm = () => {
    if (customTermInput.trim()) {
      setSavedTerms([...savedTerms, customTermInput.trim()]);
      setInvoice(prev => ({ ...prev, paymentTerms: customTermInput.trim() }));
      setCustomTermInput('');
      setIsAddingTerm(false);
    }
  };

  const recalculateTotal = (items: InvoiceItem[]): number => {
    let total = 0;
    items.forEach(item => {
      total += item.quantity * item.price;
    });
    return total;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSubmit(invoice);
  };

  const handleCancel = () => {
    onCancel();
  };

  const dueDateCalculator = () => {
    if (invoice.paymentTerms === undefined || invoice.date === undefined) {
      return '';
    }

    const term = invoice.paymentTerms.toLowerCase();
    const date = new Date(invoice.date);

    if (term.startsWith('net')) {
      const days = parseInt(term.slice(3), 10);
      if (!isNaN(days)) {
        date.setDate(date.getDate() + days);
      }
    } else if (term.includes('on receipt')) {
      // due date is same as invoice date
    } else {
      // Unknown term, just return the invoice date
      return invoice.date;
    }

    return date.toISOString().split('T')[0];
  };

  return (
    <form onSubmit={handleSubmit}>
      {/* Date */}
      <div>
        <label htmlFor="date">Date:</label>
        <input type="date" id="date" name="date" value={invoice.date} onChange={handleInputChange} max={today} />
      </div>

      {/* Payment Terms */}
      <div>
        <label htmlFor="paymentTerms">Payment Terms:</label>

**Adding Date Calculations**

I'm now adding a `dueDateCalculator` method to determine the due date based on payment terms. It handles "Net X" and "Due on Receipt" logic, returning a formatted date string. I'll integrate this with the invoice date and state, so that the dueDate is always correct. I'll add unit tests to this method.


**Implementing Due Date Logic**

Now I'm focusing on the date calculations. I've finished implementing a `dueDateCalculator` function that takes an invoice object, parses `paymentTerms` such as "Net X" or "Due on Receipt" and the invoice date, and returns the calculated due date. I'm writing tests and error handling to make sure its resilient.


**Finalizing Due Date Logic**

I've finalized `dueDateCalculator` and integrated it with form state. Now, changes to invoice date or payment terms trigger a `dueDate` recalculation. I've also refactored the component for improved readability and efficiency. Next is thorough testing.

