                    )}
                    <input type="file" accept="image/*" onChange={handleLogoUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
                  </div>
                  <div>
                      <h3 className="font-medium text-slate-900">Brand Logo</h3>
                      <p className="text-sm text-slate-500">Recommended: Square PNG or JPG</p>
