export interface BusinessProfile {
  name: string;
  email: string;
  address: string;
  phone: string;
  website?: string;
  logoUrl?: string;
  primaryColor: string;
  templateId: 'clean' | 'bold' | 'sidebar';
  country?: string;
  state?: string;
  currency: string;
}

export interface InvoiceItem {
  id: string;
  description: string;
  quantity: number;
  rate: number;
}

export interface Invoice {
  id: string;
  number: string;
  date: string;
  dueDate: string;
  paymentTerms?: string;
  clientName: string;
  clientEmail: string;
