import React, { useState } from 'react';
import { Invoice } from '../types';
import { Button } from './ui/Button';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from 'recharts';
import { analyzeFinancials } from '../services/geminiService';

interface DashboardProps {
  invoices: Invoice[];
  onCreateNew: () => void;
  onEdit: (invoice: Invoice) => void;
  currency: string;
}

export const Dashboard: React.FC<DashboardProps> = ({ invoices, onCreateNew, onEdit, currency }) => {
  const [insight, setInsight] = useState<string | null>(null);
  const [loadingInsight, setLoadingInsight] = useState(false);

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-US', { 
        style: 'currency', 
        currency: currency || 'USD',
        maximumFractionDigits: 0
    }).format(amount);
  };

  // Calculate stats
  const totalRevenue = invoices.reduce((sum, inv) => sum + inv.total, 0);
  const totalInvoices = invoices.length;

  // Prepare chart data (Last 6 months simplified)
  const chartData = invoices.reduce((acc: any[], inv) => {
    const month = new Date(inv.date).toLocaleString('default', { month: 'short' });
    const existing = acc.find(d => d.name === month);
    if (existing) {
      existing.amount += inv.total;
    } else {
      acc.push({ name: month, amount: inv.total });
    }
    return acc;
  }, []);

  const handleGenerateInsight = async () => {
    setLoadingInsight(true);
    const result = await analyzeFinancials(invoices);
    setInsight(result);
    setLoadingInsight(false);
  };

  return (
    <div className="max-w-6xl mx-auto px-6 py-8">
      <div className="flex justify-between items-center mb-8">
        <div>
           <h1 className="text-3xl font-bold text-slate-900">Dashboard</h1>
           <p className="text-slate-500">Overview of your business financials.</p>
        </div>
        <Button onClick={onCreateNew}>+ Create Invoice</Button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
           <div className="text-sm font-medium text-slate-500 uppercase tracking-wider mb-1">Total Revenue</div>
           <div className="text-3xl font-bold text-slate-900">{formatCurrency(totalRevenue)}</div>
        </div>
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
           <div className="text-sm font-medium text-slate-500 uppercase tracking-wider mb-1">Invoices Sent</div>
           <div className="text-3xl font-bold text-slate-900">{totalInvoices}</div>
        </div>
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
           <div className="text-sm font-medium text-slate-500 uppercase tracking-wider mb-1">AI Financial Insight</div>
            {insight ? (
                <p className="text-sm text-slate-700 mt-2 leading-relaxed">{insight}</p>
            ) : (
                <button 
                  onClick={handleGenerateInsight} 
                  disabled={loadingInsight || invoices.length === 0}
                  className="mt-2 text-sm text-indigo-600 font-medium hover:text-indigo-800 disabled:opacity-50 flex items-center gap-2"
                >
                    {loadingInsight ? 'Analyzing...' : 'Generate AI Insight ✨'}
                </button>
            )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
         <div className="lg:col-span-2 bg-white p-6 rounded-xl shadow-sm border border-slate-200">
             <h3 className="text-lg font-semibold text-slate-800 mb-6">Revenue Trend</h3>
             <div className="h-64">
                {chartData.length > 0 ? (
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={chartData}>
                      <XAxis dataKey="name" stroke="#94a3b8" fontSize={12} tickLine={false} axisLine={false} />
                      <YAxis stroke="#94a3b8" fontSize={12} tickLine={false} axisLine={false} tickFormatter={(val) => formatCurrency(val)} />
                      <Tooltip 
                        cursor={{fill: '#f1f5f9'}}
                        contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                        formatter={(val: number) => formatCurrency(val)}
                      />
                      <Bar dataKey="amount" fill="#0f172a" radius={[4, 4, 0, 0]} barSize={40} />
                    </BarChart>
                  </ResponsiveContainer>
                ) : (
                    <div className="h-full flex items-center justify-center text-slate-400">
                        No data to display yet.
                    </div>
                )}
             </div>
         </div>

         <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
             <div className="p-4 border-b border-slate-100 bg-slate-50">
                 <h3 className="font-semibold text-slate-800">Recent Invoices</h3>
             </div>
             <div className="divide-y divide-slate-100">
                 {invoices.length === 0 && (
                     <div className="p-8 text-center text-slate-500 text-sm">No invoices found.</div>
                 )}
                 {invoices.slice().reverse().slice(0, 5).map(inv => (
                     <div key={inv.id} className="p-4 hover:bg-slate-50 transition-colors cursor-pointer" onClick={() => onEdit(inv)}>
                         <div className="flex justify-between items-center mb-1">
                             <span className="font-medium text-slate-900">{inv.clientName || 'Draft Client'}</span>
                             <span className="text-sm font-bold text-slate-800">{formatCurrency(inv.total)}</span>
                         </div>
                         <div className="flex justify-between items-center text-xs text-slate-500">
                             <span>#{inv.number}</span>
                             <span className={`px-2 py-0.5 rounded-full ${
                                 inv.status === 'paid' ? 'bg-green-100 text-green-700' : 
                                 inv.status === 'sent' ? 'bg-blue-100 text-blue-700' : 'bg-slate-100 text-slate-600'
                             }`}>{inv.status}</span>
                         </div>
                     </div>
                 ))}
             </div>
         </div>
      </div>
    </div>
  );
};

