import React, { useState, useEffect } from 'react';
import { Invoice, InvoiceItem } from '../types';
import { Button } from './ui/Button';
import { expandLineItemDescription } from '../services/geminiService';

interface InvoiceFormProps {
  invoice: Invoice;
  onChange: (inv: Invoice) => void;
  onSave: () => void;
  onSaveDraft: () => void;
  onCancel: () => void;
  onPrint?: () => void;
  currency: string;
}

// Internal component for currency input to handle focus/blur formatting
const CurrencyInput = ({ 
    value, 
    onChange, 
    currency 
}: { 
    value: number, 
    onChange: (val: number) => void, 
    currency: string 
}) => {
    const [isFocused, setIsFocused] = useState(false);
    const [localValue, setLocalValue] = useState(value.toString());

    useEffect(() => {
        if (!isFocused) {
            setLocalValue(new Intl.NumberFormat('en-US', { 
                style: 'currency', 
                currency: currency, 
                minimumFractionDigits: 2,
                maximumFractionDigits: 2 
            }).format(value));
        }
    }, [value, currency, isFocused]);

    const handleFocus = () => {
        setIsFocused(true);
        setLocalValue(value.toString());
    };

    const handleBlur = () => {
        setIsFocused(false);
        // Clean input to just number before saving if needed, but we rely on onChange update
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const val = e.target.value;
        setLocalValue(val);
        const parsed = parseFloat(val.replace(/[^0-9.-]+/g, ''));
        if (!isNaN(parsed)) {
            onChange(parsed);
        } else {
            onChange(0);
        }
    };

    return (
        <input
            type="text"
            value={localValue}
            onChange={handleChange}
            onFocus={handleFocus}
            onBlur={handleBlur}
            className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none text-sm text-right font-mono"
        />
    );
};


export const InvoiceForm: React.FC<InvoiceFormProps> = ({ invoice, onChange, onSave, onSaveDraft, onCancel, onPrint, currency }) => {
  const [loadingItems, setLoadingItems] = useState<Record<string, boolean>>({});
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Payment Terms State
  const [availableTerms, setAvailableTerms] = useState<string[]>(['Due on Receipt', 'Net 15', 'Net 30', 'Net 45', 'Net 60']);
  const [isCustomTermMode, setIsCustomTermMode] = useState(false);
  const [customTermInput, setCustomTermInput] = useState('');

  // Load custom terms from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem('lumina_custom_terms');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setAvailableTerms(prev => Array.from(new Set([...prev, ...parsed])));
      } catch (e) {
        console.error("Failed to parse saved terms", e);
      }
    }
  }, []);

  const handleInputChange = (field: keyof Invoice, value: string) => {
    onChange({ ...invoice, [field]: value });
    if (errors[field]) {
      setErrors(prev => {
        const newErrors = { ...prev };
        delete newErrors[field];
        return newErrors;
      });
    }
  };

  const handlePaymentTermChange = (term: string) => {
    let updates: Partial<Invoice> = { paymentTerms: term };

    if (invoice.date && term) {
        if (term === 'Due on Receipt') {
            updates.dueDate = invoice.date;
        } else {
            const match = term.match(/Net (\d+)/i);
            if (match) {
                const days = parseInt(match[1]);
                const date = new Date(invoice.date);
                date.setDate(date.getDate() + days);
                if (!isNaN(date.getTime())) {
                     updates.dueDate = date.toISOString().split('T')[0];
                }
            }
        }
    }

    onChange({ ...invoice, ...updates });
  };

  const handleSaveCustomTerm = () => {
      if (!customTermInput.trim()) return;
      const term = customTermInput.trim();

      if (!availableTerms.includes(term)) {
          const newTerms = [...availableTerms, term];
          setAvailableTerms(newTerms);

          const savedCustoms = JSON.parse(localStorage.getItem('lumina_custom_terms') || '[]');
          if (!savedCustoms.includes(term)) {
              localStorage.setItem('lumina_custom_terms', JSON.stringify([...savedCustoms, term]));
          }
      }

      handlePaymentTermChange(term);
      setIsCustomTermMode(false);
      setCustomTermInput('');
  };

  const handleItemChange = (id: string, field: keyof InvoiceItem, value: string | number) => {
    const newItems = invoice.items.map(item => 
      item.id === id ? { ...item, [field]: value } : item
    );
    recalculateTotal(newItems);
  };

  const recalculateTotal = (items: InvoiceItem[]) => {
    const total = items.reduce((sum, item) => sum + (item.quantity * item.rate), 0);
    onChange({ ...invoice, items, total });
  };

  const addItem = () => {
    const newItem: InvoiceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: '',
      quantity: 1,
      rate: 0
    };
    recalculateTotal([...invoice.items, newItem]);
  };

  const removeItem = (id: string) => {
    recalculateTotal(invoice.items.filter(i => i.id !== id));
  };

  const handleSmartExpand = async (id: string, currentDesc: string) => {
    if (!currentDesc.trim()) return;

    setLoadingItems(prev => ({ ...prev, [id]: true }));
    try {
      const expanded = await expandLineItemDescription(currentDesc);
      handleItemChange(id, 'description', expanded);
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingItems(prev => ({ ...prev, [id]: false }));
    }
  };

  const validateAndSave = () => {
    const newErrors: Record<string, string> = {};
    if (!invoice.number || !invoice.number.trim()) {
      newErrors.number = "Invoice number is required";
    }
    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }
    onSave();
  };

  const saveDraft = () => {
     // For draft, we might just require an ID or even generate one
     if (!invoice.number) {
         onChange({...invoice, number: 'DRAFT'});
     }
     onSaveDraft();
  }

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
        <h3 className="text-lg font-semibold text-slate-800 mb-4">Invoice Details</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">
              Invoice Number <span className="text-red-500">*</span>
            </label>
            <input 
              type="text" 
              value={invoice.number} 
              onChange={e => handleInputChange('number', e.target.value)}
              className={`w-full px-3 py-2 border rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none ${errors.number ? 'border-red-500 bg-red-50' : 'border-slate-300'}`}
              placeholder="e.g. INV-001"
            />
            {errors.number && (
              <p className="mt-1 text-xs text-red-500 font-medium">{errors.number}</p>
            )}
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Payment Terms</label>
            {isCustomTermMode ? (
                <div className="flex gap-2">
                    <input 
                        type="text" 
                        value={customTermInput}
                        onChange={(e) => setCustomTermInput(e.target.value)}
                        placeholder="e.g. Net 90, 50% Upfront"
                        className="flex-1 px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none text-sm"
                        autoFocus
                    />
                    <Button size="sm" onClick={handleSaveCustomTerm} disabled={!customTermInput.trim()}>Save</Button>
                    <Button size="sm" variant="ghost" onClick={() => setIsCustomTermMode(false)}>✕</Button>
                </div>
            ) : (
                <select 
                    value={invoice.paymentTerms || ''} 
                    onChange={e => {
                        if (e.target.value === 'custom_plus') {
                            setIsCustomTermMode(true);
                        } else {
                            handlePaymentTermChange(e.target.value);
                        }
                    }}
                    className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none bg-white"
                >
                    <option value="">Select terms...</option>
                    {availableTerms.map(term => (
                        <option key={term} value={term}>{term}</option>
                    ))}
                    <option disabled className="text-slate-300">──────────</option>
                    <option value="custom_plus" className="font-semibold text-indigo-600">+ Create Custom Term</option>
                </select>
            )}
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Date Issued</label>
              <input 
                type="date" 
                value={invoice.date} 
                onChange={e => handleInputChange('date', e.target.value)}
                className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Due Date</label>
              <input 
                type="date" 
                value={invoice.dueDate} 
                onChange={e => handleInputChange('dueDate', e.target.value)}
                className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none"
              />
            </div>
        </div>
      </div>

      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
        <h3 className="text-lg font-semibold text-slate-800 mb-4">Client Information</h3>
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Client Name</label>
            <input 
              type="text" 
              value={invoice.clientName} 
              onChange={e => handleInputChange('clientName', e.target.value)}
              className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none"
              placeholder="e.g. Acme Corp"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Client Email</label>
            <input 
              type="email" 
              value={invoice.clientEmail} 
              onChange={e => handleInputChange('clientEmail', e.target.value)}
              className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none"
              placeholder="billing@acme.com"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Client Address</label>
            <textarea 
              value={invoice.clientAddress} 
              onChange={e => handleInputChange('clientAddress', e.target.value)}
              className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none h-20"
              placeholder="123 Business Rd..."
            />
          </div>
        </div>
      </div>

      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
        <h3 className="text-lg font-semibold text-slate-800 mb-4 flex justify-between items-center">
          <span>Items</span>
        </h3>
        <div className="space-y-4">
          {invoice.items.map((item) => (
            <div key={item.id} className="p-4 border border-slate-100 rounded-lg bg-slate-50 group">
              <div className="flex gap-4 items-start">
                 <div className="flex-1">
                   <div className="flex justify-between items-center mb-1">
                      <label className="text-xs font-semibold text-slate-500">Description</label>
                      <button 
                        onClick={() => handleSmartExpand(item.id, item.description)}
                        disabled={loadingItems[item.id] || !item.description}
                        className="text-xs flex items-center gap-1 text-indigo-600 hover:text-indigo-800 disabled:opacity-50 transition-colors"
                        title="Use AI to make this professional"
                      >
                         {loadingItems[item.id] ? (
                            <span className="animate-spin">✨</span>
                         ) : (
                            <span>✨ Smart Enhance</span>
                         )}
                      </button>
                   </div>
                   <textarea
                     value={item.description}
                     onChange={(e) => handleItemChange(item.id, 'description', e.target.value)}
                     className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none text-sm"
                     rows={2}
                     placeholder="Service description..."
                   />
                 </div>
                 <div className="w-20">
                   <label className="block text-xs font-semibold text-slate-500 mb-1">Qty</label>
                   <input
                     type="number"
                     value={item.quantity}
                     onChange={(e) => handleItemChange(item.id, 'quantity', parseFloat(e.target.value) || 0)}
                     className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none text-sm text-right"
                   />
                 </div>
                 <div className="w-28">
                   <label className="block text-xs font-semibold text-slate-500 mb-1">Rate</label>
                   <CurrencyInput 
                      value={item.rate}
                      onChange={(val) => handleItemChange(item.id, 'rate', val)}
                      currency={currency}
                   />
                 </div>
                 <div className="w-8 pt-6">
                    <button onClick={() => removeItem(item.id)} className="text-slate-400 hover:text-red-500 transition-colors">
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                        </svg>
                    </button>
                 </div>
              </div>
            </div>
          ))}

          <Button variant="secondary" onClick={addItem} className="w-full border-dashed border-2 border-slate-300 text-slate-500 hover:text-slate-700 hover:border-slate-400 bg-transparent">
            + Add Line Item
          </Button>

          <div className="flex justify-end pt-4 border-t border-slate-100">
            <div className="w-1/2 flex justify-between items-center">
                <span className="font-semibold text-slate-700">Total</span>
                <span className="text-2xl font-bold text-slate-900">
                    {new Intl.NumberFormat('en-US', { style: 'currency', currency: currency }).format(invoice.total)}
                </span>
            </div>
          </div>
        </div>
      </div>

      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
        <h3 className="text-lg font-semibold text-slate-800 mb-4">Notes & Footer</h3>
        <textarea 
            value={invoice.notes || ''}
            onChange={e => handleInputChange('notes', e.target.value)}
            className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none"
            rows={3}
            placeholder="Thank you for your business! Payment is due within 30 days."
        />
      </div>

      <div className="pt-4 border-t border-slate-200">
          <div className="flex gap-2 justify-end mb-4">
              <Button variant="secondary" size="sm" onClick={onPrint}>Download PDF</Button>
          </div>
          <div className="flex gap-4">
            <Button variant="ghost" onClick={onCancel}>Cancel</Button>
            <div className="flex-1"></div>
            <Button variant="secondary" onClick={saveDraft}>Save Draft</Button>
            <Button onClick={validateAndSave}>Save Invoice</Button>
          </div>
      </div>
    </div>
  );
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'ghost' | 'danger';
  size?: 'sm' | 'md' | 'lg';
  isLoading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  className = '', 
  isLoading,
  disabled,
  type = 'button',
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center rounded-lg font-medium transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-50 disabled:pointer-events-none";

  const variants = {
    primary: "bg-slate-900 text-white hover:bg-slate-800 focus:ring-slate-900",
    secondary: "bg-white text-slate-700 border border-slate-300 hover:bg-slate-50 focus:ring-slate-500",
    ghost: "bg-transparent text-slate-600 hover:bg-slate-100 focus:ring-slate-500",
    danger: "bg-red-600 text-white hover:bg-red-700 focus:ring-red-600",
  };

  const sizes = {
    sm: "px-3 py-1.5 text-sm",
    md: "px-4 py-2 text-sm",
    lg: "px-6 py-3 text-base",
  };

  return (
    <button
      type={type}
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${className}`}
      disabled={disabled || isLoading}
      {...props}
    >
      {isLoading ? (
        <>
          <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-current" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
          </svg>
          Loading...
        </>
      ) : children}
    </button>
  );
};

import React, { useState, useEffect } from 'react';
import { Invoice, InvoiceItem } from '../types';
import { Button } from './ui/Button';
import { expandLineItemDescription } from '../services/geminiService';

interface InvoiceFormProps {
  invoice: Invoice;
  onChange: (inv: Invoice) => void;
  onSave: () => void;
  onSaveDraft: () => void;
  onCancel: () => void;
  onPrint?: () => void;
  currency: string;
}

// Internal component for currency input to handle focus/blur formatting
const CurrencyInput = ({ 
    value, 
    onChange, 
    currency 
}: { 
    value: number, 
    onChange: (val: number) => void, 
    currency: string 
}) => {
    const [isFocused, setIsFocused] = useState(false);
    const [localValue, setLocalValue] = useState(value.toString());

    useEffect(() => {
        if (!isFocused) {
            setLocalValue(new Intl.NumberFormat('en-US', { 
                style: 'currency', 
                currency: currency, 
                minimumFractionDigits: 2,
                maximumFractionDigits: 2 
            }).format(value));
        }
    }, [value, currency, isFocused]);

    const handleFocus = () => {
        setIsFocused(true);
        setLocalValue(value.toString());
    };

    const handleBlur = () => {
        setIsFocused(false);
        // Clean input to just number before saving if needed, but we rely on onChange update
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const val = e.target.value;
        setLocalValue(val);
        const parsed = parseFloat(val.replace(/[^0-9.-]+/g, ''));
        if (!isNaN(parsed)) {
            onChange(parsed);
        } else {
            onChange(0);
        }
    };

    return (
        <input
            type="text"
            value={localValue}
            onChange={handleChange}
            onFocus={handleFocus}
            onBlur={handleBlur}
            className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none text-sm text-right font-mono"
        />
    );
};


export const InvoiceForm: React.FC<InvoiceFormProps> = ({ invoice, onChange, onSave, onSaveDraft, onCancel, onPrint, currency }) => {
  const [loadingItems, setLoadingItems] = useState<Record<string, boolean>>({});
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Payment Terms State
  const [availableTerms, setAvailableTerms] = useState<string[]>(['Due on Receipt', 'Net 15', 'Net 30', 'Net 45', 'Net 60']);
  const [isCustomTermMode, setIsCustomTermMode] = useState(false);
  const [customTermInput, setCustomTermInput] = useState('');

  // Load custom terms from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem('lumina_custom_terms');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setAvailableTerms(prev => Array.from(new Set([...prev, ...parsed])));
      } catch (e) {
        console.error("Failed to parse saved terms", e);
      }
    }
  }, []);

  const handleInputChange = (field: keyof Invoice, value: string) => {
    onChange({ ...invoice, [field]: value });
    if (errors[field]) {
      setErrors(prev => {
        const newErrors = { ...prev };
        delete newErrors[field];
        return newErrors;
      });
    }
  };

  const handlePaymentTermChange = (term: string) => {
    let updates: Partial<Invoice> = { paymentTerms: term };

    if (invoice.date && term) {
        if (term === 'Due on Receipt') {
            updates.dueDate = invoice.date;
        } else {
            const match = term.match(/Net (\d+)/i);
            if (match) {
                const days = parseInt(match[1]);
                const date = new Date(invoice.date);
                date.setDate(date.getDate() + days);
                if (!isNaN(date.getTime())) {
                     updates.dueDate = date.toISOString().split('T')[0];
                }
            }
        }
    }

    onChange({ ...invoice, ...updates });
  };

  const handleSaveCustomTerm = () => {
      if (!customTermInput.trim()) return;
      const term = customTermInput.trim();

      if (!availableTerms.includes(term)) {
          const newTerms = [...availableTerms, term];
          setAvailableTerms(newTerms);

          const savedCustoms = JSON.parse(localStorage.getItem('lumina_custom_terms') || '[]');
          if (!savedCustoms.includes(term)) {
              localStorage.setItem('lumina_custom_terms', JSON.stringify([...savedCustoms, term]));
          }
      }

      handlePaymentTermChange(term);
      setIsCustomTermMode(false);
      setCustomTermInput('');
  };

  const handleItemChange = (id: string, field: keyof InvoiceItem, value: string | number) => {
    const newItems = invoice.items.map(item => 
      item.id === id ? { ...item, [field]: value } : item
    );
    recalculateTotal(newItems);
  };

  const recalculateTotal = (items: InvoiceItem[]) => {
    const total = items.reduce((sum, item) => sum + (item.quantity * item.rate), 0);
    onChange({ ...invoice, items, total });
  };

  const addItem = () => {
    const newItem: InvoiceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: '',
      quantity: 1,
      rate: 0
    };
    recalculateTotal([...invoice.items, newItem]);
  };

  const removeItem = (id: string) => {
    recalculateTotal(invoice.items.filter(i => i.id !== id));
  };

  const handleSmartExpand = async (id: string, currentDesc: string) => {
    if (!currentDesc.trim()) return;

    setLoadingItems(prev => ({ ...prev, [id]: true }));
    try {
      const expanded = await expandLineItemDescription(currentDesc);
      handleItemChange(id, 'description', expanded);
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingItems(prev => ({ ...prev, [id]: false }));
    }
  };

  const validateAndSave = () => {
    const newErrors: Record<string, string> = {};
    if (!invoice.number || !invoice.number.trim()) {
      newErrors.number = "Invoice number is required";
    }
    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }
    onSave();
  };

  const saveDraft = () => {
     if (!invoice.number) {
         onChange({...invoice, number: 'DRAFT'});
     }
     onSaveDraft();
  }

  const handleDownloadPDF = (e: React.MouseEvent) => {
      e.preventDefault();
      if (onPrint) {
          onPrint();
      }
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
        <h3 className="text-lg font-semibold text-slate-800 mb-4">Invoice Details</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">
              Invoice Number <span className="text-red-500">*</span>
            </label>
            <input 
              type="text" 
              value={invoice.number} 
              onChange={e => handleInputChange('number', e.target.value)}
              className={`w-full px-3 py-2 border rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none ${errors.number ? 'border-red-500 bg-red-50' : 'border-slate-300'}`}
              placeholder="e.g. INV-001"
            />
            {errors.number && (
              <p className="mt-1 text-xs text-red-500 font-medium">{errors.number}</p>
            )}
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Payment Terms</label>
            {isCustomTermMode ? (
                <div className="flex gap-2">
                    <input 
                        type="text" 
                        value={customTermInput}
                        onChange={(e) => setCustomTermInput(e.target.value)}
                        placeholder="e.g. Net 90, 50% Upfront"
                        className="flex-1 px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none text-sm"
                        autoFocus
                    />
                    <Button size="sm" onClick={handleSaveCustomTerm} disabled={!customTermInput.trim()}>Save</Button>
                    <Button size="sm" variant="ghost" onClick={() => setIsCustomTermMode(false)}>✕</Button>
                </div>
            ) : (
                <select 
                    value={invoice.paymentTerms || ''} 
                    onChange={e => {
                        if (e.target.value === 'custom_plus') {
                            setIsCustomTermMode(true);
                        } else {
                            handlePaymentTermChange(e.target.value);
                        }
                    }}
                    className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none bg-white"
                >
                    <option value="">Select terms...</option>
                    {availableTerms.map(term => (
                        <option key={term} value={term}>{term}</option>
                    ))}
                    <option disabled className="text-slate-300">──────────</option>
                    <option value="custom_plus" className="font-semibold text-indigo-600">+ Create Custom Term</option>
                </select>
            )}
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Date Issued</label>
              <input 
                type="date" 
                value={invoice.date} 
                onChange={e => handleInputChange('date', e.target.value)}
                className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Due Date</label>
              <input 
                type="date" 
                value={invoice.dueDate} 
                onChange={e => handleInputChange('dueDate', e.target.value)}
                className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none"
              />
            </div>
        </div>
      </div>

      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
        <h3 className="text-lg font-semibold text-slate-800 mb-4">Client Information</h3>
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Client Name</label>
            <input 
              type="text" 
              value={invoice.clientName} 
              onChange={e => handleInputChange('clientName', e.target.value)}
              className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none"
              placeholder="e.g. Acme Corp"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Client Email</label>
            <input 
              type="email" 
              value={invoice.clientEmail} 
              onChange={e => handleInputChange('clientEmail', e.target.value)}
              className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none"
              placeholder="billing@acme.com"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Client Address</label>
            <textarea 
              value={invoice.clientAddress} 
              onChange={e => handleInputChange('clientAddress', e.target.value)}
              className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none h-20"
              placeholder="123 Business Rd..."
            />
          </div>
        </div>
      </div>

      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
        <h3 className="text-lg font-semibold text-slate-800 mb-4 flex justify-between items-center">
          <span>Items</span>
        </h3>
        <div className="space-y-4">
          {invoice.items.map((item) => (
            <div key={item.id} className="p-4 border border-slate-100 rounded-lg bg-slate-50 group">
              <div className="flex gap-4 items-start">
                 <div className="flex-1">
                   <div className="flex justify-between items-center mb-1">
                      <label className="text-xs font-semibold text-slate-500">Description</label>
                      <button 
                        onClick={() => handleSmartExpand(item.id, item.description)}
                        disabled={loadingItems[item.id] || !item.description}
                        className="text-xs flex items-center gap-1 text-indigo-600 hover:text-indigo-800 disabled:opacity-50 transition-colors"
                        title="Use AI to make this professional"
                      >
                         {loadingItems[item.id] ? (
                            <span className="animate-spin">✨</span>
                         ) : (
                            <span>✨ Smart Enhance</span>
                         )}
                      </button>
                   </div>
                   <textarea
                     value={item.description}
                     onChange={(e) => handleItemChange(item.id, 'description', e.target.value)}
                     className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none text-sm"
                     rows={2}
                     placeholder="Service description..."
                   />
                 </div>
                 <div className="w-20">
                   <label className="block text-xs font-semibold text-slate-500 mb-1">Qty</label>
                   <input
                     type="number"
                     value={item.quantity}
                     onChange={(e) => handleItemChange(item.id, 'quantity', parseFloat(e.target.value) || 0)}
                     className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none text-sm text-right"
                   />
                 </div>
                 <div className="w-28">
                   <label className="block text-xs font-semibold text-slate-500 mb-1">Rate</label>
                   <CurrencyInput 
                      value={item.rate}
                      onChange={(val) => handleItemChange(item.id, 'rate', val)}
                      currency={currency}
                   />
                 </div>
                 <div className="w-8 pt-6">
                    <button onClick={() => removeItem(item.id)} className="text-slate-400 hover:text-red-500 transition-colors">
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                        </svg>
                    </button>
                 </div>
              </div>
            </div>
          ))}

          <Button variant="secondary" onClick={addItem} className="w-full border-dashed border-2 border-slate-300 text-slate-500 hover:text-slate-700 hover:border-slate-400 bg-transparent">
            + Add Line Item
          </Button>

          <div className="flex justify-end pt-4 border-t border-slate-100">
            <div className="w-1/2 flex justify-between items-center">
                <span className="font-semibold text-slate-700">Total</span>
                <span className="text-2xl font-bold text-slate-900">
                    {new Intl.NumberFormat('en-US', { style: 'currency', currency: currency }).format(invoice.total)}
                </span>
            </div>
          </div>
        </div>
      </div>

      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
        <h3 className="text-lg font-semibold text-slate-800 mb-4">Notes & Footer</h3>
        <textarea 
            value={invoice.notes || ''}
            onChange={e => handleInputChange('notes', e.target.value)}
            className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none"
            rows={3}
            placeholder="Thank you for your business! Payment is due within 30 days."
        />
      </div>

      <div className="pt-4 border-t border-slate-200">
          <div className="flex gap-2 justify-end mb-4">
              <Button variant="secondary" size="sm" onClick={handleDownloadPDF}>Download PDF</Button>
          </div>
          <div className="flex gap-4">
            <Button variant="ghost" onClick={onCancel}>Cancel</Button>
            <div className="flex-1"></div>
            <Button variant="secondary" onClick={saveDraft}>Save Draft</Button>
            <Button onClick={validateAndSave}>Save Invoice</Button>
          </div>
      </div>
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";
import { Invoice, BusinessProfile } from "../types";

const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export const expandLineItemDescription = async (shortDescription: string): Promise<string> => {
  if (!apiKey) return shortDescription;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: `You are a professional invoicing assistant. 
      Expand the following short service description into a professional, clear, and concise invoice line item description (max 1 sentence).

      Input: "${shortDescription}"

      Output:`,
    });
    return response.text.trim();
  } catch (error) {
    console.error("Gemini API Error:", error);
    return shortDescription;
  }
};

export const analyzeFinancials = async (invoices: Invoice[]): Promise<string> => {
  if (!apiKey) return "API Key missing. Cannot generate insights.";
  if (invoices.length === 0) return "No invoice data available for analysis.";

  const dataSummary = invoices.map(inv => ({
    date: inv.date,
    amount: inv.total,
    status: inv.status
  }));

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: `Analyze this invoice data and provide a brief, encouraging financial summary (2-3 sentences). Mention the total revenue and any positive trends.

      Data: ${JSON.stringify(dataSummary)}`,
    });
    return response.text.trim();
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Could not generate financial analysis at this time.";
  }
};

export const draftInvoiceEmail = async (invoice: Invoice, profile: BusinessProfile): Promise<{ subject: string; body: string }> => {
  if (!apiKey) return { subject: `Invoice ${invoice.number}`, body: "Please find your invoice attached." };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: `Write a professional, friendly email to a client for sending an invoice.

      Business Name: ${profile.name}
      Client Name: ${invoice.clientName}
      Invoice Number: ${invoice.number}
      Amount Due: ${invoice.total} ${profile.currency}
      Due Date: ${invoice.dueDate}

      Format the output as a JSON object with "subject" and "body" fields. The body should be plain text with appropriate line breaks.`,
      config: {
          responseMimeType: "application/json"
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini API Error:", error);
    return { 
        subject: `Invoice ${invoice.number} from ${profile.name}`, 
        body: `Hi ${invoice.clientName},\n\nPlease find the invoice ${invoice.number} attached for your records.\n\nTotal: ${invoice.total} ${profile.currency}\nDue Date: ${invoice.dueDate}\n\nBest regards,\n${profile.name}` 
    };
  }
};

import React, { useState, useEffect } from 'react';
import { Invoice, BusinessProfile } from '../types';
import { Button } from './ui/Button';
import { draftInvoiceEmail } from '../services/geminiService';

interface EmailModalProps {
  invoice: Invoice;
  profile: BusinessProfile;
  onClose: () => void;
}

export const EmailModal: React.FC<EmailModalProps> = ({ invoice, profile, onClose }) => {
  const [loading, setLoading] = useState(true);
  const [emailData, setEmailData] = useState<{ subject: string; body: string } | null>(null);
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    const fetchEmail = async () => {
      const data = await draftInvoiceEmail(invoice, profile);
      setEmailData(data);
      setLoading(false);
    };
    fetchEmail();
  }, [invoice, profile]);

  const handleCopy = () => {
    if (!emailData) return;
    navigator.clipboard.writeText(`Subject: ${emailData.subject}\n\n${emailData.body}`);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleSend = () => {
    if (!emailData) return;
    const mailtoUrl = `mailto:${invoice.clientEmail}?subject=${encodeURIComponent(emailData.subject)}&body=${encodeURIComponent(emailData.body)}`;
    window.location.href = mailtoUrl;
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl overflow-hidden flex flex-col">
        <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
          <div className="flex items-center gap-2">
            <span className="text-xl">✨</span>
            <h3 className="font-bold text-slate-800">AI Email Draft</h3>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 transition-colors">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="p-8 flex-1 overflow-y-auto">
          {loading ? (
            <div className="space-y-4 animate-pulse">
              <div className="h-4 bg-slate-200 rounded w-1/4"></div>
              <div className="h-10 bg-slate-100 rounded w-full"></div>
              <div className="h-4 bg-slate-200 rounded w-1/4"></div>
              <div className="h-32 bg-slate-100 rounded w-full"></div>
            </div>
          ) : (
            <div className="space-y-6">
              <div>
                <label className="block text-xs font-bold uppercase tracking-wider text-slate-400 mb-2">Recipient</label>
                <div className="text-sm font-medium text-slate-700 bg-slate-50 px-3 py-2 rounded-md border border-slate-200">
                  {invoice.clientName} ({invoice.clientEmail || 'No email provided'})
                </div>
              </div>
              <div>
                <label className="block text-xs font-bold uppercase tracking-wider text-slate-400 mb-2">Subject</label>
                <input 
                  type="text" 
                  value={emailData?.subject || ''}
                  onChange={(e) => setEmailData(prev => prev ? { ...prev, subject: e.target.value } : null)}
                  className="w-full text-sm font-medium text-slate-700 bg-white px-3 py-2 rounded-md border border-slate-300 focus:ring-2 focus:ring-slate-900 focus:outline-none"
                />
              </div>
              <div>
                <label className="block text-xs font-bold uppercase tracking-wider text-slate-400 mb-2">Message Body</label>
                <textarea 
                  rows={8}
                  value={emailData?.body || ''}
                  onChange={(e) => setEmailData(prev => prev ? { ...prev, body: e.target.value } : null)}
                  className="w-full text-sm text-slate-600 bg-white px-3 py-2 rounded-md border border-slate-300 focus:ring-2 focus:ring-slate-900 focus:outline-none resize-none font-serif"
                />
              </div>
            </div>
          )}
        </div>

        <div className="px-6 py-4 border-t border-slate-100 flex justify-between gap-4 bg-slate-50">
          <Button variant="ghost" onClick={handleCopy}>
            {copied ? '✅ Copied!' : 'Copy Text'}
          </Button>
          <div className="flex gap-3">
             <Button variant="secondary" onClick={onClose}>Close</Button>
             <Button onClick={handleSend} disabled={loading || !invoice.clientEmail}>
                Open in Mail App
             </Button>
          </div>
        </div>
      </div>
    </div>
  );
};

