import React, { useState, useEffect } from 'react';
import { Invoice, InvoiceItem } from '../types';
import { Button } from './ui/Button';
import { expandLineItemDescription } from '../services/geminiService';

interface InvoiceFormProps {
  invoice: Invoice;
  onChange: (inv: Invoice) => void;
  onSave: () => void;
  onSaveDraft: () => void;
  onCancel: () => void;
  onPrint?: () => void;
  onSend?: () => void;
  currency: string;
  isLoadingPDF?: boolean;
}

// Internal component for currency input to handle focus/blur formatting
const CurrencyInput = ({ 
    value, 
    onChange, 
    currency 
}: { 
    value: number, 
    onChange: (val: number) => void, 
    currency: string 
}) => {
    const [isFocused, setIsFocused] = useState(false);
    const [localValue, setLocalValue] = useState(value.toString());

    useEffect(() => {
        if (!isFocused) {
            setLocalValue(new Intl.NumberFormat('en-US', { 
                style: 'currency', 
                currency: currency, 
                minimumFractionDigits: 2,
                maximumFractionDigits: 2 
            }).format(value));
        }
    }, [value, currency, isFocused]);

    const handleFocus = () => {
        setIsFocused(true);
        setLocalValue(value.toString());
    };

    const handleBlur = () => {
        setIsFocused(false);
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const val = e.target.value;
        setLocalValue(val);
        const parsed = parseFloat(val.replace(/[^0-9.-]+/g, ''));
        if (!isNaN(parsed)) {
            onChange(parsed);
        } else {
            onChange(0);
        }
    };

    return (
        <input
            type="text"
            value={localValue}
            onChange={handleChange}
            onFocus={handleFocus}
            onBlur={handleBlur}
            className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none text-sm text-right font-mono"
        />
    );
};


export const InvoiceForm: React.FC<InvoiceFormProps> = ({ invoice, onChange, onSave, onSaveDraft, onCancel, onPrint, onSend, currency, isLoadingPDF }) => {
  const [loadingItems, setLoadingItems] = useState<Record<string, boolean>>({});
  const [errors, setErrors] = useState<Record<string, string>>({});

  const [availableTerms, setAvailableTerms] = useState<string[]>(['Due on Receipt', 'Net 15', 'Net 30', 'Net 45', 'Net 60']);
  const [isCustomTermMode, setIsCustomTermMode] = useState(false);
  const [customTermInput, setCustomTermInput] = useState('');

  useEffect(() => {
    const saved = localStorage.getItem('lumina_custom_terms');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setAvailableTerms(prev => Array.from(new Set([...prev, ...parsed])));
      } catch (e) {
        console.error("Failed to parse saved terms", e);
      }
    }
  }, []);

  const handleInputChange = (field: keyof Invoice, value: string) => {
    onChange({ ...invoice, [field]: value });
    if (errors[field]) {
      setErrors(prev => {
        const newErrors = { ...prev };
        delete newErrors[field];
        return newErrors;
      });
    }
  };

  const handlePaymentTermChange = (term: string) => {
    let updates: Partial<Invoice> = { paymentTerms: term };

    if (invoice.date && term) {
        if (term === 'Due on Receipt') {
            updates.dueDate = invoice.date;
        } else {
            const match = term.match(/Net (\d+)/i);
            if (match) {
                const days = parseInt(match[1]);
                const date = new Date(invoice.date);
                date.setDate(date.getDate() + days);
                if (!isNaN(date.getTime())) {
                     updates.dueDate = date.toISOString().split('T')[0];
                }
            }
        }
    }

    onChange({ ...invoice, ...updates });
  };

  const handleSaveCustomTerm = () => {
      if (!customTermInput.trim()) return;
      const term = customTermInput.trim();

      if (!availableTerms.includes(term)) {
          const newTerms = [...availableTerms, term];
          setAvailableTerms(newTerms);

          const savedCustoms = JSON.parse(localStorage.getItem('lumina_custom_terms') || '[]');
          if (!savedCustoms.includes(term)) {
              localStorage.setItem('lumina_custom_terms', JSON.stringify([...savedCustoms, term]));
          }
      }

      handlePaymentTermChange(term);
      setIsCustomTermMode(false);
      setCustomTermInput('');
  };

  const handleItemChange = (id: string, field: keyof InvoiceItem, value: string | number) => {
    const newItems = invoice.items.map(item => 
      item.id === id ? { ...item, [field]: value } : item
    );
    recalculateTotal(newItems);
  };

  const recalculateTotal = (items: InvoiceItem[]) => {
    const total = items.reduce((sum, item) => sum + (item.quantity * item.rate), 0);
    onChange({ ...invoice, items, total });
  };

  const addItem = () => {
    const newItem: InvoiceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: '',
      quantity: 1,
      rate: 0
    };
    recalculateTotal([...invoice.items, newItem]);
  };

  const removeItem = (id: string) => {
    recalculateTotal(invoice.items.filter(i => i.id !== id));
  };

  const handleSmartExpand = async (id: string, currentDesc: string) => {
    if (!currentDesc.trim()) return;

    setLoadingItems(prev => ({ ...prev, [id]: true }));
    try {
      const expanded = await expandLineItemDescription(currentDesc);
      handleItemChange(id, 'description', expanded);
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingItems(prev => ({ ...prev, [id]: false }));
    }
  };

  const validateAndSave = () => {
    const newErrors: Record<string, string> = {};
    if (!invoice.number || !invoice.number.trim()) {
      newErrors.number = "Invoice number is required";
    }
    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }
    onSave();
  };

  const saveDraft = () => {
     if (!invoice.number) {
         onChange({...invoice, number: 'DRAFT'});
     }
     onSaveDraft();
  }

  const handleDownloadPDF = (e: React.MouseEvent) => {
      e.preventDefault();
      if (onPrint) onPrint();
  };

  const handleSendEmail = (e: React.MouseEvent) => {
      e.preventDefault();
      if (onSend) onSend();
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
        <h3 className="text-lg font-semibold text-slate-800 mb-4">Invoice Details</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">
              Invoice Number <span className="text-red-500">*</span>
            </label>
            <input 
              type="text" 
              value={invoice.number} 
              onChange={e => handleInputChange('number', e.target.value)}
              className={`w-full px-3 py-2 border rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none ${errors.number ? 'border-red-500 bg-red-50' : 'border-slate-300'}`}
              placeholder="e.g. INV-001"
            />
            {errors.number && (
              <p className="mt-1 text-xs text-red-500 font-medium">{errors.number}</p>
            )}
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Payment Terms</label>
            {isCustomTermMode ? (
                <div className="flex gap-2">
                    <input 
                        type="text" 
                        value={customTermInput}
                        onChange={(e) => setCustomTermInput(e.target.value)}
                        placeholder="e.g. Net 90, 50% Upfront"
                        className="flex-1 px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none text-sm"
                        autoFocus
                    />
                    <Button size="sm" onClick={handleSaveCustomTerm} disabled={!customTermInput.trim()}>Save</Button>
                    <Button size="sm" variant="ghost" onClick={() => setIsCustomTermMode(false)}>✕</Button>
                </div>
            ) : (
                <select 
                    value={invoice.paymentTerms || ''} 
                    onChange={e => {
                        if (e.target.value === 'custom_plus') {
                            setIsCustomTermMode(true);
                        } else {
                            handlePaymentTermChange(e.target.value);
                        }
                    }}
                    className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none bg-white"
                >
                    <option value="">Select terms...</option>
                    {availableTerms.map(term => (
                        <option key={term} value={term}>{term}</option>
                    ))}
                    <option disabled className="text-slate-300">──────────</option>
                    <option value="custom_plus" className="font-semibold text-indigo-600">+ Create Custom Term</option>
                </select>
            )}
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Date Issued</label>
              <input 
                type="date" 
                value={invoice.date} 
                onChange={e => handleInputChange('date', e.target.value)}
                className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Due Date</label>
              <input 
                type="date" 
                value={invoice.dueDate} 
                onChange={e => handleInputChange('dueDate', e.target.value)}
                className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none"
              />
            </div>
        </div>
      </div>

      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
        <h3 className="text-lg font-semibold text-slate-800 mb-4">Client Information</h3>
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Client Name</label>
            <input 
              type="text" 
              value={invoice.clientName} 
              onChange={e => handleInputChange('clientName', e.target.value)}
              className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none"
              placeholder="e.g. Acme Corp"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Client Email</label>
            <input 
              type="email" 
              value={invoice.clientEmail} 
              onChange={e => handleInputChange('clientEmail', e.target.value)}
              className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none"
              placeholder="billing@acme.com"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Client Address</label>
            <textarea 
              value={invoice.clientAddress} 
              onChange={e => handleInputChange('clientAddress', e.target.value)}
              className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none h-20"
              placeholder="123 Business Rd..."
            />
          </div>
        </div>
      </div>

      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
        <h3 className="text-lg font-semibold text-slate-800 mb-4 flex justify-between items-center">
          <span>Items</span>
        </h3>
        <div className="space-y-4">
          {invoice.items.map((item) => (
            <div key={item.id} className="p-4 border border-slate-100 rounded-lg bg-slate-50 group">
              <div className="flex gap-4 items-start">
                 <div className="flex-1">
                   <div className="flex justify-between items-center mb-1">
                      <label className="text-xs font-semibold text-slate-500">Description</label>
                      <button 
                        onClick={() => handleSmartExpand(item.id, item.description)}
                        disabled={loadingItems[item.id] || !item.description}
                        className="text-xs flex items-center gap-1 text-indigo-600 hover:text-indigo-800 disabled:opacity-50 transition-colors"
                      >
                         {loadingItems[item.id] ? <span className="animate-spin text-sm">✨</span> : <span>✨ AI Enhance</span>}
                      </button>
                   </div>
                   <textarea
                     value={item.description}
                     onChange={(e) => handleItemChange(item.id, 'description', e.target.value)}
                     className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none text-sm"
                     rows={2}
                     placeholder="Service description..."
                   />
                 </div>
                 <div className="w-20">
                   <label className="block text-xs font-semibold text-slate-500 mb-1">Qty</label>
                   <input
                     type="number"
                     value={item.quantity}
                     onChange={(e) => handleItemChange(item.id, 'quantity', parseFloat(e.target.value) || 0)}
                     className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none text-sm text-right"
                   />
                 </div>
                 <div className="w-28">
                   <label className="block text-xs font-semibold text-slate-500 mb-1">Rate</label>
                   <CurrencyInput 
                      value={item.rate}
                      onChange={(val) => handleItemChange(item.id, 'rate', val)}
                      currency={currency}
                   />
                 </div>
                 <div className="w-8 pt-6">
                    <button onClick={() => removeItem(item.id)} className="text-slate-400 hover:text-red-500 transition-colors">
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                        </svg>
                    </button>
                 </div>
              </div>
            </div>
          ))}

          <Button variant="secondary" onClick={addItem} className="w-full border-dashed border-2 border-slate-300 text-slate-500 hover:text-slate-700 hover:border-slate-400 bg-transparent">
            + Add Line Item
          </Button>

          <div className="flex justify-end pt-4 border-t border-slate-100">
            <div className="w-1/2 flex justify-between items-center">
                <span className="font-semibold text-slate-700">Total</span>
                <span className="text-2xl font-bold text-slate-900">
                    {new Intl.NumberFormat('en-US', { style: 'currency', currency: currency }).format(invoice.total)}
                </span>
            </div>
          </div>
        </div>
      </div>

      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
        <h3 className="text-lg font-semibold text-slate-800 mb-4">Notes & Footer</h3>
        <textarea 
            value={invoice.notes || ''}
            onChange={e => handleInputChange('notes', e.target.value)}
            className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none"
            rows={3}
            placeholder="Thank you for your business! Payment is due within 30 days."
        />
      </div>

      <div className="pt-4 border-t border-slate-200">
          <div className="flex gap-2 justify-end mb-4">
              <Button variant="ghost" size="sm" onClick={handleSendEmail} disabled={!invoice.clientName}>
                <span>✉️ Send to Client</span>
              </Button>
              <Button variant="secondary" size="sm" onClick={handleDownloadPDF} isLoading={isLoadingPDF}>
                <span>{isLoadingPDF ? 'Generating...' : 'Download PDF'}</span>
              </Button>
          </div>
          <div className="flex gap-4">
            <Button variant="ghost" onClick={onCancel}>Cancel</Button>
            <div className="flex-1"></div>
            <Button variant="secondary" onClick={saveDraft}>Save Draft</Button>
            <Button onClick={validateAndSave}>Save Invoice</Button>
          </div>
      </div>
    </div>
  );
};

