import { InvoicePreview } from './components/InvoicePreview';
import { Button } from './components/ui/Button';
import { EmailModal } from './components/EmailModal';
import { ProductManager } from './components/ProductManager';

// Mock Data / Defaults
const defaultProfile: BusinessProfile = {
  name: '',
  email: '',
  address: '',
  phone: '',
  primaryColor: '#0f172a',
  templateId: 'clean',
  currency: 'USD',
  country: '',
  state: '',
  logoShape: 'square',
  taxes: [],
};

const defaultInvoice: Invoice = {
  id: '',
  number: 'INV-001',
  date: new Date().toISOString().split('T')[0],
  dueDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
  paymentTerms: 'Net 30',
  clientName: '',
  clientEmail: '',
  clientAddress: '',
  items: [{ id: '1', description: '', quantity: 1, rate: 0 }],
  status: 'draft',
  total: 0,
  notes: '',
};

function App() {
  const [view, setView] = useState<'onboarding' | 'dashboard' | 'editor' | 'products'>('onboarding');
  const [profile, setProfile] = useState<BusinessProfile>(defaultProfile);
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [currentInvoice, setCurrentInvoice] = useState<Invoice>(defaultInvoice);
  const [isEditingExisting, setIsEditingExisting] = useState(false);
  const [showEmailModal, setShowEmailModal] = useState(false);
  const [isDownloading, setIsDownloading] = useState(false);

  // Load from LocalStorage on mount
  useEffect(() => {
    const savedProfile = localStorage.getItem('lumina_profile');
    const savedInvoices = localStorage.getItem('lumina_invoices');
    const savedProducts = localStorage.getItem('lumina_products');

    if (savedProfile) {
      setProfile(JSON.parse(savedProfile));
      setView('dashboard');
    }
    if (savedInvoices) {
      setInvoices(JSON.parse(savedInvoices));
    }
    if (savedProducts) {
      setProducts(JSON.parse(savedProducts));
    }
  }, []);

  const saveProfile = (newProfile: BusinessProfile) => {
    setProfile(newProfile);
    localStorage.setItem('lumina_profile', JSON.stringify(newProfile));
    setView('dashboard');
  };

  const handleCreateNew = () => {
    const nextNum = invoices.length + 1;
    setCurrentInvoice({
        ...defaultInvoice,
        id: Math.random().toString(36).substr(2, 9),
        number: `INV-${nextNum.toString().padStart(3, '0')}`,
        date: new Date().toISOString().split('T')[0],
        items: [{ id: '1', description: '', quantity: 1, rate: 0 }],
        total: 0
    });
    setIsEditingExisting(false);
    setView('editor');
  };

  const handleEditInvoice = (inv: Invoice) => {
      setCurrentInvoice(inv);
      setIsEditingExisting(true);
      setView('editor');
  };

  const handleSaveInvoice = (status: 'draft' | 'sent' | 'paid' = 'draft') => {
      const invoiceToSave = { ...currentInvoice, status };
      let updatedInvoices;
      if (isEditingExisting) {
          updatedInvoices = invoices.map(inv => inv.id === invoiceToSave.id ? invoiceToSave : inv);
      } else {
          updatedInvoices = [...invoices, invoiceToSave];
      }
      setInvoices(updatedInvoices);
      localStorage.setItem('lumina_invoices', JSON.stringify(updatedInvoices));
      setView('dashboard');
  };

  const handleUpdateProducts = (newProducts: Product[]) => {
    setProducts(newProducts);
    localStorage.setItem('lumina_products', JSON.stringify(newProducts));
  };

  const handlePrint = async () => {
      const element = document.getElementById('invoice-capture-area');
      if (!element) {
          window.print();
          return;
      }

      setIsDownloading(true);

      const opt = {
          margin: 0,
          filename: `${currentInvoice.number || 'Invoice'}.pdf`,
          image: { type: 'jpeg', quality: 0.98 },
          html2canvas: { scale: 2, useCORS: true, letterRendering: true },
          jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
      };

      try {
          if ((window as any).html2pdf) {
              await (window as any).html2pdf().from(element).set(opt).save();
          } else {
              window.print();
          }
      } catch (err) {
          console.error('PDF Generation Error:', err);
          window.print();
      } finally {
          setIsDownloading(false);
      }
  };

  if (view === 'onboarding') {
    return <Onboarding initialProfile={profile} onComplete={saveProfile} onUpdateProducts={handleUpdateProducts} />;
  }

  if (view === 'dashboard') {
    return (
        <div className="min-h-screen bg-slate-50">
            <nav className="bg-white border-b border-slate-200 px-6 py-4 flex justify-between items-center">
                <div className="flex items-center gap-3">
                    <div className="w-8 h-8 rounded bg-slate-900 flex items-center justify-center text-white font-bold">L</div>
                    <span className="font-bold text-slate-800 tracking-tight">Lumina Invoice</span>
                </div>
                <div className="flex gap-4 items-center">
                     <button 
                        onClick={() => setView('products')} 
                        className="text-sm font-medium text-slate-600 hover:text-slate-900 transition-colors"
                     >
                        Inventory
                     </button>
                     <span className="text-slate-200">|</span>
                     <span className="text-sm font-medium text-slate-600">{profile.name}</span>
                     <button onClick={() => setView('onboarding')} className="text-xs text-slate-400 hover:text-slate-600 underline">Settings</button>
                </div>
            </nav>
            <Dashboard 
                invoices={invoices} 
                onCreateNew={handleCreateNew} 
                onEdit={handleEditInvoice} 
                currency={profile.currency} 
                onManageProducts={() => setView('products')}
            />
        </div>
    );
  }

  if (view === 'products') {
    return (
        <div className="min-h-screen bg-slate-50">
            <nav className="bg-white border-b border-slate-200 px-6 py-4 flex justify-between items-center">
                <div className="flex items-center gap-3">
                    <Button variant="ghost" size="sm" onClick={() => setView('dashboard')}>&larr; Back</Button>
                    <span className="font-bold text-slate-800 tracking-tight">Product Inventory</span>
                </div>
            </nav>
            <ProductManager 
                products={products} 
                onUpdate={handleUpdateProducts} 
                currency={profile.currency} 
            />
        </div>
    );
  }

  // Editor View (Split Screen)
  return (
    <div className="min-h-screen bg-slate-100 flex flex-col h-screen overflow-hidden print:h-auto print:overflow-visible print:bg-white">
      <header className="bg-white border-b border-slate-200 px-6 py-3 flex justify-between items-center z-30 shrink-0 no-print">
         <div className="flex items-center gap-4">
             <Button variant="ghost" size="sm" onClick={() => setView('dashboard')}>&larr; Dashboard</Button>
             <span className="text-slate-300">|</span>
             <h2 className="font-semibold text-slate-800">{isEditingExisting ? 'Edit Invoice' : 'New Invoice'}</h2>
         </div>
         <div className="flex items-center gap-3">
             <Button variant="ghost" size="sm" onClick={() => setShowEmailModal(true)} disabled={!currentInvoice.clientName}>
                <span>✉️ Send to Client</span>
             </Button>
             <Button variant="secondary" onClick={handlePrint} isLoading={isDownloading}>
                {isDownloading ? 'Generating...' : 'Download PDF'}
             </Button>
         </div>
      </header>

      <div className="flex-1 flex overflow-hidden print:block print:h-auto print:overflow-visible">
         {/* Left: Form */}
         <div className="w-1/2 overflow-y-auto p-8 border-r border-slate-200 bg-slate-50 no-print">
            <InvoiceForm 
                invoice={currentInvoice} 
                onChange={setCurrentInvoice} 
                onSave={() => handleSaveInvoice('sent')}
                onSaveDraft={() => handleSaveInvoice('draft')}
                onCancel={() => setView('dashboard')}
                onPrint={handlePrint}
                onSend={() => setShowEmailModal(true)}
                currency={profile.currency}
                isLoadingPDF={isDownloading}
                products={products}
                taxes={profile.taxes}
            />
         </div>

         {/* Right: Preview */}
         <div className="w-1/2 bg-slate-500 overflow-y-auto p-8 flex justify-center items-start print:w-full print:p-0 print:m-0 print:bg-white print:overflow-visible print:h-auto print:block">
             <div id="invoice-capture-area" className="bg-white shadow-2xl scale-90 origin-top print:scale-100 print:shadow-none w-full max-w-[800px] print:w-full print:max-w-none">
                <InvoicePreview profile={profile} invoice={currentInvoice} />
             </div>
         </div>
      </div>

      {showEmailModal && (
        <EmailModal 
          invoice={currentInvoice} 
          profile={profile} 
          onClose={() => setShowEmailModal(false)} 
        />
      )}
    </div>
  );
}

export default App;

import React, { useState, useEffect } from 'react';
import { Invoice, InvoiceItem, Product, TaxConfig } from '../types';
import { Button } from './ui/Button';
import { expandLineItemDescription } from '../services/geminiService';

interface InvoiceFormProps {
  invoice: Invoice;
  onChange: (inv: Invoice) => void;
  onSave: () => void;
  onSaveDraft: () => void;
  onCancel: () => void;
  onPrint?: () => void;
  onSend?: () => void;
  currency: string;
  isLoadingPDF?: boolean;
  products: Product[];
  taxes: TaxConfig[];
}

const CurrencyInput = ({ 
    value, 
    onChange, 
    currency 
}: { 
    value: number, 
    onChange: (val: number) => void, 
    currency: string 
}) => {
    const [isFocused, setIsFocused] = useState(false);
    const [localValue, setLocalValue] = useState(value.toString());

    useEffect(() => {
        if (!isFocused) {
            setLocalValue(new Intl.NumberFormat('en-US', { 
                style: 'currency', 
                currency: currency, 
                minimumFractionDigits: 2,
                maximumFractionDigits: 2 
            }).format(value));
        }
    }, [value, currency, isFocused]);

    const handleFocus = () => {
        setIsFocused(true);
        setLocalValue(value.toString());
    };

    const handleBlur = () => {
        setIsFocused(false);
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const val = e.target.value;
        setLocalValue(val);
        const parsed = parseFloat(val.replace(/[^0-9.-]+/g, ''));
        if (!isNaN(parsed)) {
            onChange(parsed);
        } else {
            onChange(0);
        }
    };

    return (
        <input
            type="text"
            value={localValue}
            onChange={handleChange}
            onFocus={handleFocus}
            onBlur={handleBlur}
            className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:outline-none text-sm text-right font-mono"
        />
    );
};

export const InvoiceForm: React.FC<InvoiceFormProps> = ({ 
  invoice, onChange, onSave, onSaveDraft, onCancel, onPrint, onSend, currency, isLoadingPDF, products, taxes 
}) => {
  const [loadingItems, setLoadingItems] = useState<Record<string, boolean>>({});
  const [errors, setErrors] = useState<Record<string, string>>({});

  const [availableTerms, setAvailableTerms] = useState<string[]>(['Due on Receipt', 'Net 15', 'Net 30', 'Net 45', 'Net 60']);
  const [isCustomTermMode, setIsCustomTermMode] = useState(false);
  const [customTermInput, setCustomTermInput] = useState('');

  useEffect(() => {
    const saved = localStorage.getItem('lumina_custom_terms');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setAvailableTerms(prev => Array.from(new Set([...prev, ...parsed])));
      } catch (e) {
        console.error("Failed to parse saved terms", e);
      }
    }
  }, []);

  const handleInputChange = (field: keyof Invoice, value: any) => {
    const updatedInvoice = { ...invoice, [field]: value };
    recalculateTotal(updatedInvoice.items, updatedInvoice.appliedTaxId);

    if (errors[field]) {
      setErrors(prev => {
        const newErrors = { ...prev };
        delete newErrors[field];
        return newErrors;
      });
    }
  };

  const handlePaymentTermChange = (term: string) => {
    let updates: Partial<Invoice> = { paymentTerms: term };
    if (invoice.date && term) {
        if (term === 'Due on Receipt') {
            updates.dueDate = invoice.date;
        } else {
            const match = term.match(/Net (\d+)/i);
            if (match) {
                const days = parseInt(match[1]);
                const date = new Date(invoice.date);
                date.setDate(date.getDate() + days);
                if (!isNaN(date.getTime())) {
                     updates.dueDate = date.toISOString().split('T')[0];
                }
            }
        }
    }
    onChange({ ...invoice, ...updates });
  };

  const handleItemChange = (id: string, field: keyof InvoiceItem, value: any) => {
    const newItems = invoice.items.map(item => 
      item.id === id ? { ...item, [field]: value } : item
    );
    recalculateTotal(newItems, invoice.appliedTaxId);
  };

  const handleProductSelect = (itemId: string, productId: string) => {
      const product = products.find(p => p.id === productId);
      if (!product) return;

      const newItems = invoice.items.map(item => 
        item.id === itemId ? { 
            ...item, 
            description: product.name, 
            rate: product.price,
            productId: productId
        } : item
      );
      recalculateTotal(newItems, invoice.appliedTaxId);
  };

  const recalculateTotal = (items: InvoiceItem[], taxId?: string) => {
    const subtotal = items.reduce((sum, item) => sum + (item.quantity * item.rate), 0);
    let taxTotal = 0;
    if (taxId) {
        const tax = taxes.find(t => t.id === taxId);
        if (tax) {
            taxTotal = subtotal * (tax.rate / 100);
        }
    }
    onChange({ ...invoice, items, total: subtotal + taxTotal, taxTotal, appliedTaxId: taxId });
  };

  const addItem = () => {
    const newItem: InvoiceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: '',
      quantity: 1,
      rate: 0
    };
    recalculateTotal([...invoice.items, newItem], invoice.appliedTaxId);
  };

  const removeItem = (id: string) => {
    recalculateTotal(invoice.items.filter(i => i.id !== id), invoice.appliedTaxId);
  };

  const handleSmartExpand = async (id: string, currentDesc: string) => {
    if (!currentDesc.trim()) return;
    setLoadingItems(prev => ({ ...prev, [id]: true }));
    try {
      const expanded = await expandLineItemDescription(currentDesc);
      handleItemChange(id, 'description', expanded);
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingItems(prev => ({ ...prev, [id]: false }));
    }
  };

  return (
    <div className="space-y-6 pb-20">
      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
        <h3 className="text-lg font-semibold text-slate-800 mb-4">Invoice Details</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Invoice Number</label>
            <input 
              type="text" 
              value={invoice.number} 
              onChange={e => handleInputChange('number', e.target.value)}
              className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Payment Terms</label>
            <select 
                value={invoice.paymentTerms || ''} 
                onChange={e => handlePaymentTermChange(e.target.value)}
                className="w-full px-3 py-2 border border-slate-300 rounded-md bg-white"
            >
                <option value="">Select terms...</option>
                {availableTerms.map(term => <option key={term} value={term}>{term}</option>)}
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Date Issued</label>
            <input type="date" value={invoice.date} onChange={e => handleInputChange('date', e.target.value)} className="w-full px-3 py-2 border border-slate-300 rounded-md" />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Due Date</label>
            <input type="date" value={invoice.dueDate} onChange={e => handleInputChange('dueDate', e.target.value)} className="w-full px-3 py-2 border border-slate-300 rounded-md" />
          </div>
        </div>
      </div>

      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
        <h3 className="text-lg font-semibold text-slate-800 mb-4">Client Information</h3>
        <div className="space-y-4">
          <input type="text" value={invoice.clientName} onChange={e => handleInputChange('clientName', e.target.value)} className="w-full px-3 py-2 border border-slate-300 rounded-md" placeholder="Client Name" />
          <input type="email" value={invoice.clientEmail} onChange={e => handleInputChange('clientEmail', e.target.value)} className="w-full px-3 py-2 border border-slate-300 rounded-md" placeholder="Client Email" />
          <textarea value={invoice.clientAddress} onChange={e => handleInputChange('clientAddress', e.target.value)} className="w-full px-3 py-2 border border-slate-300 rounded-md h-20" placeholder="Client Address" />
        </div>
      </div>

      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
        <h3 className="text-lg font-semibold text-slate-800 mb-4">Items</h3>
        <div className="space-y-4">
          {invoice.items.map((item) => (
            <div key={item.id} className="p-4 border border-slate-100 rounded-lg bg-slate-50">
              <div className="grid grid-cols-12 gap-3 mb-2">
                  <div className="col-span-8">
                      <select 
                        value={item.productId || ''} 
                        onChange={(e) => handleProductSelect(item.id, e.target.value)}
                        className="w-full px-2 py-1 text-xs border border-slate-200 rounded bg-white mb-2"
                      >
                          <option value="">-- Choose from Inventory --</option>
                          {products.map(p => <option key={p.id} value={p.id}>{p.name} ({new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(p.price)})</option>)}
                      </select>
                      <div className="flex justify-between items-center mb-1">
                        <label className="text-[10px] font-bold text-slate-400 uppercase">Description</label>
                        <button onClick={() => handleSmartExpand(item.id, item.description)} className="text-[10px] text-indigo-600 hover:text-indigo-800 flex items-center gap-1">
                            {loadingItems[item.id] ? <span className="animate-spin">✨</span> : <span>✨ AI Expand</span>}
                        </button>
                      </div>
                      <textarea value={item.description} onChange={(e) => handleItemChange(item.id, 'description', e.target.value)} className="w-full px-3 py-2 border border-slate-300 rounded-md text-sm" rows={2} />
                  </div>
                  <div className="col-span-2">
                      <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Qty</label>
                      <input type="number" value={item.quantity} onChange={(e) => handleItemChange(item.id, 'quantity', parseFloat(e.target.value) || 0)} className="w-full px-3 py-2 border border-slate-300 rounded-md text-sm text-right" />
                  </div>
                  <div className="col-span-2">
                      <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Rate</label>
                      <CurrencyInput value={item.rate} onChange={(val) => handleItemChange(item.id, 'rate', val)} currency={currency} />
                  </div>
              </div>
              <div className="flex justify-end">
                  <button onClick={() => removeItem(item.id)} className="text-xs text-red-500 hover:underline">Remove Item</button>
              </div>
            </div>
          ))}
          <Button variant="secondary" onClick={addItem} className="w-full py-2 border-dashed border-2 border-slate-200 bg-transparent text-slate-500">+ Add Line Item</Button>

          <div className="pt-4 border-t border-slate-100 flex flex-col items-end space-y-2">
              <div className="flex items-center gap-3 w-1/2">
                  <span className="text-sm font-medium text-slate-500 whitespace-nowrap">Apply Tax:</span>
                  <select 
                    value={invoice.appliedTaxId || ''} 
                    onChange={(e) => recalculateTotal(invoice.items, e.target.value)}
                    className="flex-1 px-3 py-1.5 border border-slate-300 rounded-md text-sm bg-white"
                  >
                      <option value="">No Tax</option>
                      {taxes.map(t => <option key={t.id} value={t.id}>{t.name} ({t.rate}%)</option>)}
                  </select>
              </div>
              <div className="w-1/2 border-t border-slate-50 pt-2 flex justify-between">
                  <span className="font-semibold text-slate-800">Total</span>
                  <span className="text-xl font-bold text-slate-900">{new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(invoice.total)}</span>
              </div>
          </div>
        </div>
      </div>

      <div className="pt-6 border-t border-slate-200 flex justify-between">
          <Button variant="ghost" onClick={onCancel}>Cancel</Button>
          <div className="flex gap-3">
              <Button variant="secondary" onClick={onSaveDraft}>Save Draft</Button>
              <Button onClick={onSave}>Finish Invoice</Button>
          </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Product } from '../types';
import { Button } from './ui/Button';

interface ProductManagerProps {
  products: Product[];
  onUpdate: (products: Product[]) => void;
  currency: string;
}

export const ProductManager: React.FC<ProductManagerProps> = ({ products, onUpdate, currency }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState({ name: '', price: 0 });

  const handleSave = () => {
      if (!form.name) return;

      let newProducts;
      if (editingId) {
          newProducts = products.map(p => p.id === editingId ? { ...p, ...form } : p);
      } else {
          newProducts = [...products, { id: Math.random().toString(36).substr(2, 9), ...form }];
      }

      onUpdate(newProducts);
      reset();
  };

  const reset = () => {
      setIsAdding(false);
      setEditingId(null);
      setForm({ name: '', price: 0 });
  };

  const startEdit = (p: Product) => {
      setEditingId(p.id);
      setForm({ name: p.name, price: p.price });
      setIsAdding(true);
  };

  const handleDelete = (id: string) => {
      if (confirm('Are you sure you want to delete this product?')) {
          onUpdate(products.filter(p => p.id !== id));
      }
  };

  return (
    <div className="max-w-4xl mx-auto px-6 py-12">
      <div className="flex justify-between items-center mb-8">
          <div>
              <h2 className="text-2xl font-bold text-slate-900">Inventory</h2>
              <p className="text-slate-500">Manage your recurring services and products.</p>
          </div>
          <Button onClick={() => setIsAdding(true)} disabled={isAdding}>+ Add Product</Button>
      </div>

      {isAdding && (
          <div className="bg-white p-6 rounded-xl border border-indigo-100 shadow-md mb-8 animate-in fade-in slide-in-from-top-4 duration-300">
              <h3 className="font-semibold text-slate-800 mb-4">{editingId ? 'Edit Product' : 'Add New Product'}</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Product/Service Name</label>
                      <input 
                        type="text" 
                        value={form.name} 
                        onChange={e => setForm({...form, name: e.target.value})}
                        className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500"
                        placeholder="e.g. Website Design"
                      />
                  </div>
                  <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Standard Price ({currency})</label>
                      <input 
                        type="number" 
                        value={form.price} 
                        onChange={e => setForm({...form, price: parseFloat(e.target.value) || 0})}
                        className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-indigo-500"
                      />
                  </div>
              </div>
              <div className="flex justify-end gap-3 mt-6">
                  <Button variant="ghost" onClick={reset}>Cancel</Button>
                  <Button onClick={handleSave}>Save Product</Button>
              </div>
          </div>
      )}

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
          <table className="w-full text-left">
              <thead>
                  <tr className="bg-slate-50 border-b border-slate-200">
                      <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase">Product Name</th>
                      <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase text-right">Standard Price</th>
                      <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase text-right">Actions</th>
                  </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                  {products.length === 0 ? (
                      <tr>
                          <td colSpan={3} className="px-6 py-12 text-center text-slate-400">No products in inventory yet.</td>
                      </tr>
                  ) : (
                      products.map(p => (
                          <tr key={p.id} className="hover:bg-slate-50 transition-colors">
                              <td className="px-6 py-4 font-medium text-slate-900">{p.name}</td>
                              <td className="px-6 py-4 text-right text-slate-600 font-mono">
                                  {new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(p.price)}
                              </td>
                              <td className="px-6 py-4 text-right space-x-3">
                                  <button onClick={() => startEdit(p)} className="text-sm text-indigo-600 hover:underline">Edit</button>
                                  <button onClick={() => handleDelete(p.id)} className="text-sm text-red-500 hover:underline">Delete</button>
                              </td>
                          </tr>
                      ))
                  )}
              </tbody>
          </table>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { BusinessProfile, Invoice, Product, TaxConfig } from '../types';
import { Button } from './ui/Button';
import { InvoicePreview } from './InvoicePreview';

interface OnboardingProps {
  initialProfile: BusinessProfile;
  onComplete: (profile: BusinessProfile) => void;
  onUpdateProducts: (products: Product[]) => void;
}

const dummyInvoice: Invoice = {
  id: 'preview',
  number: 'INV-001',
  date: new Date().toISOString().split('T')[0],
  dueDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
  paymentTerms: 'Net 30',
  clientName: 'Sample Client',
  clientEmail: 'client@example.com',
  clientAddress: '123 Client St\nSan Francisco, CA 94105',
  items: [
    { id: '1', description: 'Professional Services', quantity: 1, rate: 1200 },
    { id: '2', description: 'Consulting Fee', quantity: 5, rate: 150 },
  ],
  status: 'draft',
  total: 1950,
  notes: 'Thank you for your business!'
};

const CURRENCIES = [
  { code: 'USD', symbol: '$', name: 'US Dollar' },
  { code: 'EUR', symbol: '€', name: 'Euro' },
  { code: 'GBP', symbol: '£', name: 'British Pound' },
  { code: 'CAD', symbol: '$', name: 'Canadian Dollar' },
  { code: 'AUD', symbol: '$', name: 'Australian Dollar' },
  { code: 'JPY', symbol: '¥', name: 'Japanese Yen' },
  { code: 'INR', symbol: '₹', name: 'Indian Rupee' },
];

export const Onboarding: React.FC<OnboardingProps> = ({ initialProfile, onComplete, onUpdateProducts }) => {
  const [step, setStep] = useState(1);
  const [profile, setProfile] = useState<BusinessProfile>(() => {
    const saved = localStorage.getItem('lumina_onboarding_draft');
    return saved ? { ...initialProfile, ...JSON.parse(saved) } : initialProfile;
  });
  const [onboardingProducts, setOnboardingProducts] = useState<Product[]>([]);

  useEffect(() => {
    localStorage.setItem('lumina_onboarding_draft', JSON.stringify(profile));
  }, [profile]);

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const url = URL.createObjectURL(e.target.files[0]);
      setProfile(prev => ({ ...prev, logoUrl: url }));
    }
  };

  const addTax = () => {
      setProfile({
          ...profile,
          taxes: [...profile.taxes, { id: Math.random().toString(36).substr(2,9), name: '', rate: 0 }]
      });
  };

  const removeTax = (id: string) => {
      setProfile({ ...profile, taxes: profile.taxes.filter(t => t.id !== id) });
  };

  const handleTaxChange = (id: string, field: keyof TaxConfig, value: any) => {
      setProfile({
          ...profile,
          taxes: profile.taxes.map(t => t.id === id ? { ...t, [field]: value } : t)
      });
  };

  const addProd = () => {
    setOnboardingProducts([...onboardingProducts, { id: Math.random().toString(36).substr(2, 9), name: '', price: 0 }]);
  };

  const handleProdChange = (id: string, field: keyof Product, value: any) => {
    setOnboardingProducts(onboardingProducts.map(p => p.id === id ? { ...p, [field]: value } : p));
  };

  const handleFinish = () => {
      localStorage.removeItem('lumina_onboarding_draft');
      onUpdateProducts(onboardingProducts.filter(p => p.name));
      onComplete(profile);
  };

  return (
    <div className="min-h-screen bg-slate-50 py-12 px-4">
      <div className="max-w-6xl mx-auto">
        <div className="text-center mb-10">
          <h1 className="text-4xl font-bold text-slate-900 mb-2">Welcome to Lumina</h1>
          <p className="text-slate-500">Step {step} of 3: {step === 1 ? 'Brand Identity' : step === 2 ? 'Taxes' : 'Products'}</p>
        </div>

        <div className="bg-white rounded-2xl shadow-xl border border-slate-200 overflow-hidden flex flex-col lg:flex-row">
          <div className="p-8 space-y-8 flex-1">

              {step === 1 && (
                  <div className="space-y-6">
                    <div className="flex items-center gap-6">
                        <div className={`h-24 w-24 flex items-center justify-center bg-slate-100 border-2 border-dashed border-slate-300 relative group overflow-hidden ${profile.logoShape === 'circle' ? 'rounded-full' : 'rounded-lg'}`}>
                            {profile.logoUrl ? <img src={profile.logoUrl} className="h-full w-full object-contain" style={{ clipPath: profile.logoShape === 'triangle' ? 'polygon(50% 0%, 0% 100%, 100% 100%)' : 'none' }} /> : <span className="text-xs text-slate-400">Logo</span>}
                            <input type="file" onChange={handleLogoUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
                        </div>
                        <div className="flex-1">
                            <label className="block text-sm font-medium text-slate-700 mb-1">Business Name</label>
                            <input type="text" value={profile.name} onChange={e => setProfile({...profile, name: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-md" />
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div className="col-span-2">
                             <label className="block text-sm font-medium text-slate-700 mb-1">Address</label>
                             <textarea value={profile.address} onChange={e => setProfile({...profile, address: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-md h-20" />
                        </div>
                        <div>
                             <label className="block text-sm font-medium text-slate-700 mb-1">Email</label>
                             <input type="email" value={profile.email} onChange={e => setProfile({...profile, email: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-md" />
                        </div>
                        <div>
                             <label className="block text-sm font-medium text-slate-700 mb-1">Currency</label>
                             <select value={profile.currency} onChange={e => setProfile({...profile, currency: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-md bg-white">
                                 {CURRENCIES.map(c => <option key={c.code} value={c.code}>{c.code}</option>)}
                             </select>
                        </div>
                    </div>
                  </div>
              )}

              {step === 2 && (
                  <div className="space-y-6">
                      <div className="flex justify-between items-center">
                        <h3 className="text-lg font-bold text-slate-800">Tax Settings</h3>
                        <Button size="sm" variant="secondary" onClick={addTax}>+ Add Tax Type</Button>
                      </div>
                      <div className="space-y-4">
                        {profile.taxes.length === 0 && <p className="text-sm text-slate-400">No taxes configured. You can skip this.</p>}
                        {profile.taxes.map(t => (
                            <div key={t.id} className="flex gap-3 items-end bg-slate-50 p-4 rounded-lg">
                                <div className="flex-1">
                                    <label className="text-[10px] uppercase font-bold text-slate-400">Tax Name (e.g. VAT)</label>
                                    <input type="text" value={t.name} onChange={e => handleTaxChange(t.id, 'name', e.target.value)} className="w-full px-3 py-2 border border-slate-300 rounded-md text-sm" />
                                </div>
                                <div className="w-24">
                                    <label className="text-[10px] uppercase font-bold text-slate-400">Rate (%)</label>
                                    <input type="number" value={t.rate} onChange={e => handleTaxChange(t.id, 'rate', parseFloat(e.target.value) || 0)} className="w-full px-3 py-2 border border-slate-300 rounded-md text-sm" />
                                </div>
                                <button onClick={() => removeTax(t.id)} className="mb-2 text-red-400 hover:text-red-600">✕</button>
                            </div>
                        ))}
                      </div>
                  </div>
              )}

              {step === 3 && (
                  <div className="space-y-6">
                      <div className="flex justify-between items-center">
                        <h3 className="text-lg font-bold text-slate-800">Standard Products/Services</h3>
                        <Button size="sm" variant="secondary" onClick={addProd}>+ Add Item</Button>
                      </div>
                      <p className="text-sm text-slate-500">Save items you bill for frequently to speed up invoice creation.</p>
                      <div className="space-y-4 overflow-y-auto max-h-96 pr-2">
                        {onboardingProducts.map(p => (
                            <div key={p.id} className="flex gap-3 items-end bg-slate-50 p-4 rounded-lg">
                                <div className="flex-1">
                                    <input type="text" value={p.name} onChange={e => handleProdChange(p.id, 'name', e.target.value)} className="w-full px-3 py-2 border border-slate-300 rounded-md text-sm" placeholder="Service Name" />
                                </div>
                                <div className="w-32">
                                    <input type="number" value={p.price} onChange={e => handleProdChange(p.id, 'price', parseFloat(e.target.value) || 0)} className="w-full px-3 py-2 border border-slate-300 rounded-md text-sm" placeholder="Price" />
                                </div>
                            </div>
                        ))}
                      </div>
                  </div>
              )}

              <div className="pt-8 border-t border-slate-100 flex justify-between">
                  {step > 1 ? <Button variant="ghost" onClick={() => setStep(step - 1)}>Back</Button> : <div></div>}
                  <Button onClick={() => step < 3 ? setStep(step + 1) : handleFinish()}>
                      {step === 3 ? 'Finish Setup' : 'Continue'}
                  </Button>
              </div>
          </div>

          <div className="hidden lg:block w-1/2 bg-slate-200 p-8 flex items-center justify-center">
             <div className="transform scale-[0.6] origin-top shadow-2xl rounded-lg overflow-hidden bg-white">
                <div className="w-[800px] pointer-events-none">
                    <InvoicePreview profile={profile} invoice={dummyInvoice} />
                </div>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

