import React, { useState } from 'react';
import { Invoice } from '../types';
import { Button } from './ui/Button';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from 'recharts';
import { analyzeFinancials } from '../services/geminiService';

interface DashboardProps {
  invoices: Invoice[];
  onCreateNew: () => void;
  onEdit: (invoice: Invoice) => void;
  currency: string;
  onManageProducts: () => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ invoices, onCreateNew, onEdit, currency, onManageProducts }) => {
  const [insight, setInsight] = useState<string | null>(null);
  const [loadingInsight, setLoadingInsight] = useState(false);

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-US', { 
        style: 'currency', 
        currency: currency || 'USD',
        maximumFractionDigits: 0
    }).format(amount);
  };

  const totalRevenue = invoices.reduce((sum, inv) => sum + inv.total, 0);
  const totalInvoices = invoices.length;

  const chartData = invoices.reduce((acc: any[], inv) => {
    const month = new Date(inv.date).toLocaleString('default', { month: 'short' });
    const existing = acc.find(d => d.name === month);
    if (existing) {
      existing.amount += inv.total;
    } else {
      acc.push({ name: month, amount: inv.total });
    }
    return acc;
  }, []);

  const handleGenerateInsight = async () => {
    setLoadingInsight(true);
    const result = await analyzeFinancials(invoices);
    setInsight(result);
    setLoadingInsight(false);
  };

  return (
    <div className="max-w-6xl mx-auto px-6 py-8">
      <div className="flex justify-between items-center mb-8">
        <div>
           <h1 className="text-3xl font-bold text-slate-900">Dashboard</h1>
           <p className="text-slate-500">Professional invoicing for your brand.</p>
        </div>
        <div className="flex gap-3">
            <Button variant="secondary" onClick={onManageProducts}>Inventory</Button>
            <Button onClick={onCreateNew}>+ Create Invoice</Button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
           <div className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Total Revenue</div>
           <div className="text-3xl font-bold text-slate-900">{formatCurrency(totalRevenue)}</div>
        </div>
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
           <div className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Invoices</div>
           <div className="text-3xl font-bold text-slate-900">{totalInvoices}</div>
        </div>
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
           <div className="text-xs font-bold text-indigo-400 uppercase tracking-widest mb-1">AI Financial Insight</div>
            {insight ? (
                <p className="text-xs text-slate-700 mt-2 leading-relaxed">{insight}</p>
            ) : (
                <button 
                  onClick={handleGenerateInsight} 
                  disabled={loadingInsight || invoices.length === 0}
                  className="mt-2 text-xs text-indigo-600 font-bold hover:underline"
                >
                    {loadingInsight ? 'Analyzing...' : 'Analyze Business ✨'}
                </button>
            )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
         <div className="lg:col-span-2 bg-white p-6 rounded-xl shadow-sm border border-slate-200">
             <h3 className="text-lg font-semibold text-slate-800 mb-6">Earnings Trend</h3>
             <div className="h-64">
                {chartData.length > 0 ? (
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={chartData}>
                      <XAxis dataKey="name" stroke="#cbd5e1" fontSize={10} tickLine={false} axisLine={false} />
                      <YAxis stroke="#cbd5e1" fontSize={10} tickLine={false} axisLine={false} tickFormatter={(val) => formatCurrency(val)} />
                      <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }} />
                      <Bar dataKey="amount" fill="#0f172a" radius={[4, 4, 0, 0]} barSize={32} />
                    </BarChart>
                  </ResponsiveContainer>
                ) : (
                    <div className="h-full flex items-center justify-center text-slate-300 italic text-sm">
                        Create your first invoice to see data.
                    </div>
                )}
             </div>
         </div>

         <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col">
             <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                 <h3 className="font-semibold text-slate-800">History</h3>
                 <span className="text-[10px] font-bold text-slate-400 uppercase">Latest 5</span>
             </div>
             <div className="divide-y divide-slate-100 flex-1 overflow-y-auto">
                 {invoices.length === 0 && <div className="p-8 text-center text-slate-400 text-sm">Empty.</div>}
                 {invoices.slice().reverse().slice(0, 5).map(inv => (
                     <div key={inv.id} className="p-4 hover:bg-slate-50 transition-colors cursor-pointer" onClick={() => onEdit(inv)}>
                         <div className="flex justify-between items-center mb-1">
                             <span className="font-semibold text-slate-900 text-sm truncate max-w-[120px]">{inv.clientName || 'Draft'}</span>
                             <span className="text-sm font-bold text-slate-800">{formatCurrency(inv.total)}</span>
                         </div>
                         <div className="flex justify-between items-center text-[10px] text-slate-400 font-bold uppercase tracking-wider">
                             <span>#{inv.number}</span>
                             <span className={inv.status === 'paid' ? 'text-green-500' : inv.status === 'sent' ? 'text-blue-500' : 'text-slate-400'}>{inv.status}</span>
                         </div>
                     </div>
                 ))}
             </div>
         </div>
      </div>
    </div>
  );
};

