                  onClick={handleGenerateInsight} 
                  disabled={loadingInsight || invoices.length === 0}
                  className="mt-2 text-xs text-indigo-600 font-bold hover:underline flex items-center gap-1"
                >
                    {loadingInsight ? 'Analyzing...' : 'Analyze Business ✨'}
                </button>
            )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
         <div className="lg:col-span-2 bg-white p-6 rounded-xl shadow-sm border border-slate-200">
             <h3 className="text-lg font-semibold text-slate-800 mb-6">Earnings Trend</h3>
             <div className="h-64">
                {chartData.length > 0 ? (
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={chartData}>
                      <XAxis dataKey="name" stroke="#cbd5e1" fontSize={10} tickLine={false} axisLine={false} />
                      <YAxis stroke="#cbd5e1" fontSize={10} tickLine={false} axisLine={false} tickFormatter={(val) => formatCurrency(val)} />
                      <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }} />
                      <Bar dataKey="amount" fill="#0f172a" radius={[4, 4, 0, 0]} barSize={32} />
                    </BarChart>
                  </ResponsiveContainer>
                ) : (
                    <div className="h-full flex items-center justify-center text-slate-300 italic text-sm">
                        Create your first invoice to see data.
                    </div>
                )}
             </div>
         </div>

         <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col">
             <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                 <h3 className="font-semibold text-slate-800">History</h3>
                 <span className="text-[10px] font-bold text-slate-400 uppercase">Latest 5</span>
             </div>
             <div className="divide-y divide-slate-100 flex-1 overflow-y-auto max-h-[400px]">
                 {invoices.length === 0 && <div className="p-8 text-center text-slate-400 text-sm italic">No invoices found.</div>}
                 {invoices.slice().reverse().slice(0, 5).map(inv => (
                     <div key={inv.id} className="p-4 hover:bg-slate-50 transition-colors cursor-pointer group" onClick={() => onEdit(inv)}>
                         <div className="flex justify-between items-center mb-1">
                             <span className="font-semibold text-slate-900 text-sm truncate max-w-[120px] group-hover:text-indigo-600 transition-colors">{inv.clientName || 'Unnamed Draft'}</span>
                             <span className="text-sm font-bold text-slate-800">{formatCurrency(inv.total)}</span>
                         </div>
                         <div className="flex justify-between items-center text-[10px] text-slate-400 font-bold uppercase tracking-wider">
                             <span>#{inv.number}</span>
                             <span className={`
                               ${inv.status === 'paid' ? 'text-green-500' : 
                                 inv.status === 'sent' ? 'text-blue-500' : 
                                 'text-slate-400'}
                             `}>{inv.status}</span>
                         </div>
                     </div>
                 ))}
             </div>
         </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { BusinessProfile, Invoice, Product, TaxConfig } from './types';
import { Onboarding } from './components/Onboarding';
import { Dashboard } from './components/Dashboard';
import { InvoiceForm } from './components/InvoiceForm';
import { InvoicePreview } from './components/InvoicePreview';
import { Button } from './components/ui/Button';
import { EmailModal } from './components/EmailModal';
import { ProductManager } from './components/ProductManager';

// Mock Data / Defaults
const defaultProfile: BusinessProfile = {
  name: '',
  email: '',
  address: '',
  phone: '',
  primaryColor: '#0f172a',
  templateId: 'clean',
  currency: 'USD',
  country: '',
  state: '',
  logoShape: 'square',
  taxes: [],
};

const defaultInvoice: Invoice = {
  id: '',
  number: 'INV-001',
  date: new Date().toISOString().split('T')[0],
  dueDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
  paymentTerms: 'Net 30',
  clientName: '',
  clientEmail: '',
  clientPhone: '',
  clientAddress: '',
  items: [{ id: '1', description: '', quantity: 1, rate: 0 }],
  status: 'draft',
  total: 0,
  notes: '',
};

function App() {
  const [view, setView] = useState<'onboarding' | 'dashboard' | 'editor' | 'products' | 'clients'>('onboarding');
  const [profile, setProfile] = useState<BusinessProfile>(defaultProfile);
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [currentInvoice, setCurrentInvoice] = useState<Invoice>(defaultInvoice);
  const [isEditingExisting, setIsEditingExisting] = useState(false);
  const [showEmailModal, setShowEmailModal] = useState(false);
  const [isDownloading, setIsDownloading] = useState(false);

  // Load from LocalStorage on mount
  useEffect(() => {
    const savedProfile = localStorage.getItem('lumina_profile');
    const savedInvoices = localStorage.getItem('lumina_invoices');
    const savedProducts = localStorage.getItem('lumina_products');

    if (savedProfile) {
      setProfile(JSON.parse(savedProfile));
      setView('dashboard');
    }
    if (savedInvoices) {
      setInvoices(JSON.parse(savedInvoices));
    }
    if (savedProducts) {
      setProducts(JSON.parse(savedProducts));
    }
  }, []);

  const saveProfile = (newProfile: BusinessProfile) => {
    setProfile(newProfile);
    localStorage.setItem('lumina_profile', JSON.stringify(newProfile));
    setView('dashboard');
  };

  const handleCreateNew = () => {
    const nextNum = invoices.length + 1;
    setCurrentInvoice({
        ...defaultInvoice,
        id: Math.random().toString(36).substr(2, 9),
        number: `INV-${nextNum.toString().padStart(3, '0')}`,
        date: new Date().toISOString().split('T')[0],
        items: [{ id: '1', description: '', quantity: 1, rate: 0 }],
        total: 0
    });
    setIsEditingExisting(false);
    setView('editor');
  };

  const handleEditInvoice = (inv: Invoice) => {
      setCurrentInvoice(inv);
      setIsEditingExisting(true);
      setView('editor');
  };

  const handleSaveInvoice = (status: 'draft' | 'sent' | 'paid' = 'draft') => {
      const invoiceToSave = { ...currentInvoice, status };
      let updatedInvoices;
      if (isEditingExisting) {
          updatedInvoices = invoices.map(inv => inv.id === invoiceToSave.id ? invoiceToSave : inv);
      } else {
          updatedInvoices = [...invoices, invoiceToSave];
      }
      setInvoices(updatedInvoices);
      localStorage.setItem('lumina_invoices', JSON.stringify(updatedInvoices));
      setView('dashboard');
  };

  const handleUpdateProducts = (newProducts: Product[]) => {
    setProducts(newProducts);
    localStorage.setItem('lumina_products', JSON.stringify(newProducts));
  };

  const handlePrint = async () => {
      const element = document.getElementById('invoice-capture-area');
      if (!element) {
          window.print();
          return;
      }

      setIsDownloading(true);

      const opt = {
          margin: 0,
          filename: `${currentInvoice.number || 'Invoice'}.pdf`,
          image: { type: 'jpeg', quality: 0.98 },
          html2canvas: { scale: 2, useCORS: true, letterRendering: true },
          jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
      };

      try {
          if ((window as any).html2pdf) {
              await (window as any).html2pdf().from(element).set(opt).save();
          } else {
              window.print();
          }
      } catch (err) {
          console.error('PDF Generation Error:', err);
          window.print();
      } finally {
          setIsDownloading(false);
      }
  };

  if (view === 'onboarding') {
    return <Onboarding initialProfile={profile} onComplete={saveProfile} onUpdateProducts={handleUpdateProducts} />;
  }

  if (view === 'dashboard' || view === 'clients') {
    return (
        <div className="min-h-screen bg-slate-50">
            <Dashboard 
                invoices={invoices} 
                onCreateNew={handleCreateNew} 
                onEdit={handleEditInvoice} 
                currency={profile.currency} 
                onManageProducts={() => setView('products')}
                onOpenSettings={() => setView('onboarding')}
                onOpenClients={() => setView('clients')}
                onOpenAccount={() => setView('onboarding')}
                profileName={profile.name}
            />
            {view === 'clients' && (
                <div className="fixed inset-0 z-50 bg-white p-8 animate-in slide-in-from-bottom duration-300">
                    <div className="max-w-4xl mx-auto">
                        <div className="flex justify-between items-center mb-8">
                            <h2 className="text-3xl font-bold">Client List</h2>
                            <Button onClick={() => setView('dashboard')}>Back to Dashboard</Button>
                        </div>
                        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
                            <table className="w-full text-left">
                                <thead className="bg-slate-50 border-b border-slate-200">
                                    <tr>
                                        <th className="p-4 font-bold text-slate-600">Name</th>
                                        <th className="p-4 font-bold text-slate-600">Email</th>
                                        <th className="p-4 font-bold text-slate-600">Phone</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {Array.from(new Set(invoices.map(i => i.clientEmail))).map(email => {
                                        const client = invoices.find(i => i.clientEmail === email);
                                        if (!client) return null;
                                        return (
                                            <tr key={email} className="border-b border-slate-50 hover:bg-slate-50">
                                                <td className="p-4 font-medium">{client.clientName}</td>
                                                <td className="p-4 text-slate-500">{client.clientEmail}</td>
                                                <td className="p-4 text-slate-500">{client.clientPhone || 'N/A'}</td>
                                            </tr>
                                        );
                                    })}
                                    {invoices.length === 0 && (
                                        <tr><td colSpan={3} className="p-8 text-center text-slate-400">No clients in your history yet.</td></tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
  }

  if (view === 'products') {
    return (
        <div className="min-h-screen bg-slate-50">
            <nav className="bg-white border-b border-slate-200 px-6 py-4 flex justify-between items-center">
                <div className="flex items-center gap-3">
                    <Button variant="ghost" size="sm" onClick={() => setView('dashboard')}>&larr; Back</Button>
                    <span className="font-bold text-slate-800 tracking-tight">Product Inventory</span>
                </div>
            </nav>
            <ProductManager 
                products={products} 
                onUpdate={handleUpdateProducts} 
                currency={profile.currency} 
            />
        </div>
    );
  }

  // Editor View (Split Screen)
  return (
    <div className="min-h-screen bg-slate-100 flex flex-col h-screen overflow-hidden print:h-auto print:overflow-visible print:bg-white">
      <header className="bg-white border-b border-slate-200 px-6 py-3 flex justify-between items-center z-30 shrink-0 no-print">
         <div className="flex items-center gap-4">
             <Button variant="ghost" size="sm" onClick={() => setView('dashboard')}>&larr; Dashboard</Button>
             <span className="text-slate-300">|</span>
             <h2 className="font-semibold text-slate-800">{isEditingExisting ? 'Edit Invoice' : 'New Invoice'}</h2>
         </div>
         <div className="flex items-center gap-3">
             <Button variant="ghost" size="sm" onClick={() => setShowEmailModal(true)} disabled={!currentInvoice.clientName || !currentInvoice.clientEmail}>
                <span>✉️ Send to Client</span>
             </Button>
             <Button variant="secondary" onClick={handlePrint} isLoading={isDownloading}>
                {isDownloading ? 'Generating...' : 'Download PDF'}
             </Button>
         </div>
      </header>

      <div className="flex-1 flex overflow-hidden print:block print:h-auto print:overflow-visible">
         {/* Left: Form */}
         <div className="w-full md:w-1/2 overflow-y-auto p-4 md:p-8 border-r border-slate-200 bg-slate-50 no-print">
            <InvoiceForm 
                invoice={currentInvoice} 
                onChange={setCurrentInvoice} 
                onSave={() => handleSaveInvoice('sent')}
                onSaveDraft={() => handleSaveInvoice('draft')}
                onCancel={() => setView('dashboard')}
                onPrint={handlePrint}
                onSend={() => setShowEmailModal(true)}
                currency={profile.currency}
                isLoadingPDF={isDownloading}
                products={products}
                taxes={profile.taxes}
            />
         </div>

         {/* Right: Preview */}
         <div className="hidden md:flex w-1/2 bg-slate-500 overflow-y-auto p-8 justify-center items-start print:w-full print:p-0 print:m-0 print:bg-white print:overflow-visible print:h-auto print:block">
             <div id="invoice-capture-area" className="bg-white shadow-2xl scale-90 origin-top print:scale-100 print:shadow-none w-full max-w-[800px] print:w-full print:max-w-none">
                <InvoicePreview profile={profile} invoice={currentInvoice} />
             </div>
         </div>
      </div>

      {showEmailModal && (
        <EmailModal 
          invoice={currentInvoice} 
          profile={profile} 
          onClose={() => setShowEmailModal(false)} 
        />
      )}
    </div>
  );
}

export default App;

import React from 'react';
