  invoice: Invoice;
}

export const InvoicePreview: React.FC<InvoicePreviewProps> = ({ profile, invoice }) => {

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: profile.currency || 'USD' }).format(amount);
  };

  const getTaxLine = () => {
    if (!invoice.appliedTaxId) return null;
    const tax = profile.taxes.find(t => t.id === invoice.appliedTaxId);
    if (!tax) return null;
    return { name: tax.name, rate: tax.rate, amount: invoice.taxTotal || 0 };
  };

  const Logo = ({ className = "h-12" }: { className?: string }) => {
      if (!profile.logoUrl) return null;
      const shapeStyle = profile.logoShape === 'circle' ? 'rounded-full' : 'rounded';
      const clipStyle = profile.logoShape === 'triangle' ? { clipPath: 'polygon(50% 0%, 0% 100%, 100% 100%)' } : {};
      return <img src={profile.logoUrl} className={`${className} object-contain ${shapeStyle}`} style={clipStyle} />;
  };

  const SummaryTotals = () => {
      const taxLine = getTaxLine();
      const subtotal = invoice.items.reduce((sum, i) => sum + (i.quantity * i.rate), 0);
      return (
          <div className="w-full space-y-2 border-t border-slate-100 pt-4">
              <div className="flex justify-between text-slate-500 text-sm">
                  <span>Subtotal</span>
                  <span>{formatCurrency(subtotal)}</span>
              </div>
              {taxLine && (
                  <div className="flex justify-between text-slate-500 text-sm">
                      <span>{taxLine.name} ({taxLine.rate}%)</span>
                      <span>{formatCurrency(taxLine.amount)}</span>
